            FDChoice(label: "Lui demander de te montrer son geste", hint: "Tu lui as demandé de te montrer le geste, sérieusement. Il te l'a appris, et tu l'as sorti en match deux mois plus tard.",
                     effects: [FDEffect(attr: .dribble, delta: 2), FDEffect(rel: "vestiaire", delta: 4), FDEffect(rel: "coach", delta: -2)]),
        ]),
    FDSceneDef(
        id: "ent_double_seance", category: "Entraînement", minAge: 17, maxAge: 34,
        location: "Terrain d'entraînement", character: "Préparateur physique",
        text: "Défaite 4-0 dimanche, double séance imposée lundi : terrain le matin, salle l'après-midi, silence obligatoire entre les deux. Le groupe traîne les pieds depuis le réveil et le staff regarde qui donne le ton. La deuxième séance n'a pas encore commencé.",
        choices: [
            FDChoice(label: "Donner le rythme au groupe", hint: "Tu as donné le rythme au groupe toute la journée. Le staff l'a vu, et tes jambes s'en souvenaient encore mercredi.",
                     effects: [FDEffect(attr: .leadership, delta: 3), FDEffect(cond: "fatigue", delta: 14), FDEffect(rel: "coach", delta: 5)]),
            FDChoice(label: "Suivre sans en faire plus", hint: "Tu as suivi le mouvement sans en faire plus. Journée passée, rien gagné, rien perdu.",
                     effects: [FDEffect(cond: "fatigue", delta: 8)]),
        ]),
    FDSceneDef(
        id: "cri_relegation", category: "Crise", minAge: 19, maxAge: 35,
        location: "Vestiaire", character: "Le capitaine",
        text: "Trois matchs pour sauver le club, et le vestiaire est devenu irrespirable : plus personne ne parle au réfectoire, deux joueurs cherchent déjà un point de chute, et les supporters attendent sur le parking tous les jours. Le capitaine a dit tout haut qu'il ne savait plus quoi dire.",
        choices: [
            FDChoice(label: "Prendre la parole devant le groupe", hint: "Tu as pris la parole devant le groupe, sans discours préparé. Ça a remis quelque chose debout pour une semaine au moins.",
                     effects: [FDEffect(attr: .leadership, delta: 5), FDEffect(rel: "vestiaire", delta: 5), FDEffect(cond: "fatigue", delta: 4)]),
            FDChoice(label: "Laisser les cadres gérer", hint: "Tu as laissé les cadres gérer. Ils ont géré à moitié, et personne ne t'a rien reproché.",
                     effects: [FDEffect(attr: .sangfroid, delta: 2), FDEffect(cond: "fatigue", delta: 5)]),
            FDChoice(label: "Te concentrer sur ton propre match", hint: "Tu t'es concentré sur ton propre match, uniquement. Tu as été bon, le club est descendu, et tu es parti l'été suivant.",
                     effects: [FDEffect(attr: .determination, delta: 3), FDEffect(rel: "vestiaire", delta: -3)]),
        ]),
    FDSceneDef(
        id: "cri_president_menace", category: "Crise", minAge: 20, maxAge: 35,
        location: "Salle de réunion", character: "Président du club",
        text: "Le président descend au vestiaire après la défaite, ce qu'il n'a fait que deux fois en cinq ans. Il parle de primes coupées, d'effectif à vendre, de joueurs qui « ne méritent pas le maillot ». Le coach ne dit rien. Vingt-cinq joueurs regardent leurs chaussures.",
        choices: [
            FDChoice(label: "Répondre devant le groupe", hint: "Tu as répondu devant le groupe, calmement mais en face. Le vestiaire ne l'a pas oublié — le président non plus.",
                     effects: [FDEffect(attr: .leadership, delta: 4), FDEffect(rel: "president", delta: -8), FDEffect(rel: "vestiaire", delta: 8)]),
            FDChoice(label: "Encaisser en silence", hint: "Tu as encaissé en silence comme les autres. Il est reparti satisfait, et rien n'a changé.",
                     effects: [FDEffect(rel: "president", delta: 3), FDEffect(cond: "moral", delta: -4)]),
        ]),
    FDSceneDef(
        id: "cri_vente_club", category: "Crise", minAge: 19, maxAge: 35,
        location: "Salle de presse", character: "Directeur sportif",
        text: "Le club a été racheté pendant la trêve. Le nouveau propriétaire tient sa première conférence de presse et parle de « tout reconstruire » sans jamais préciser ce qu'il garde. Ton contrat court encore deux ans, ce qui ne veut plus dire grand-chose depuis ce matin.",
        choices: [
            FDChoice(label: "Demander des garanties écrites", hint: "Tu as exigé des garanties écrites avant de continuer. Tu les as obtenues, et ils ont trouvé ça déplacé.",
                     effects: [FDEffect(rel: "president", delta: -3), FDEffect(rel: "agent", delta: 5), FDEffect(attr: .sangfroid, delta: 2)]),
            FDChoice(label: "Faire confiance au projet", hint: "Tu as fait confiance au projet, sans rien demander. Six mois plus tard, la moitié du vestiaire avait changé.",
                     effects: [FDEffect(rel: "president", delta: 6), FDEffect(cond: "confiance", delta: 2), FDEffect(cond: "fatigue", delta: 5)]),
        ]),
    FDSceneDef(
        id: "cri_supporters_bus", category: "Crise", minAge: 19, maxAge: 35,
        location: "Parking du stade", character: "Supporters en colère",
        text: "Cinquième défaite de suite. Le bus ne peut pas sortir du parking : deux cents personnes devant, des fumigènes, des maillots jetés contre les vitres. Le chauffeur a coupé le moteur. Le staff dit d'attendre la police, et ils réclament un joueur, n'importe lequel.",
        choices: [
            FDChoice(label: "Descendre leur parler", hint: "Tu es descendu leur parler, seul, sous les insultes. Ça a duré vingt minutes, et le bus est reparti sans casse.",
                     effects: [FDEffect(cond: "reputation", delta: 6), FDEffect(rel: "fans", delta: 8), FDEffect(cond: "moral", delta: -3)]),
            FDChoice(label: "Rester dans le bus", hint: "Tu es resté dans le bus avec les autres. La police a fini par arriver, et l'image a tourné toute la nuit.",
                     effects: [FDEffect(rel: "fans", delta: -6)]),
            FDChoice(label: "Filmer la scène", hint: "Tu as filmé la scène depuis la vitre. Ta vidéo a fait des millions de vues, et le club a ouvert une procédure interne.",
                     effects: [FDEffect(rel: "media", delta: 4), FDEffect(rel: "fans", delta: -8), FDEffect(cond: "reputation", delta: -3)]),
        ]),
    FDSceneDef(
        id: "cri_salaires", category: "Crise", minAge: 19, maxAge: 35,
        location: "Bureau du club", character: "Directeur financier",
        text: "Le directeur financier te reçoit avec un tableau : la trésorerie ne tient pas jusqu'en juin. Il demande aux joueurs les mieux payés d'étaler leur salaire sur deux ans, en commençant par toi parce que « tu es raisonnable ». Rien ne t'y oblige, et tout le monde le sait.",
        choices: [
            FDChoice(label: "Accepter", hint: "Tu as accepté l'étalement. Le club a passé l'hiver, et personne à l'extérieur n'a jamais su ce que tu avais fait.",
                     effects: [FDEffect(rel: "president", delta: 9), FDEffect(money: -20000, delta: 0), FDEffect(cond: "reputation", delta: 4)]),
            FDChoice(label: "Refuser", hint: "Tu as refusé, contrat en main. Tu es dans ton droit, et la direction a retenu ton nom.",
                     effects: [FDEffect(rel: "president", delta: -7), FDEffect(money: 0, delta: 0)]),
            FDChoice(label: "Accepter contre une prolongation", hint: "Tu as accepté contre une prolongation signée le jour même. Ils ont grimacé, ils ont signé, et tu as gagné deux ans.",
                     effects: [FDEffect(rel: "president", delta: 5), FDEffect(rel: "agent", delta: 4), FDEffect(cond: "fatigue", delta: 5)]),
        ]),
    FDSceneDef(
        id: "cri_entraineur_interim", category: "Crise", minAge: 19, maxAge: 35,
        location: "Terrain d'entraînement", character: "Entraîneur intérimaire",
        text: "Le coach a été limogé mardi. L'adjoint prend le groupe en intérim, sans savoir s'il tiendra trois semaines ou six mois, et il te demande d'être son relais sur le terrain le temps que ça dure. Il n'a aucune autorité et il le sait mieux que personne.",
        choices: [
            FDChoice(label: "Accepter", hint: "Tu as accepté d'être son relais. Vous avez sauvé la saison, et le coach suivant est arrivé avec un a priori sur toi.",
                     effects: [FDEffect(attr: .leadership, delta: 5), FDEffect(rel: "coach", delta: 6), FDEffect(cond: "fatigue", delta: 5)]),
            FDChoice(label: "Refuser, la situation est trop instable", hint: "Tu as refusé, la situation étant trop instable. Il a trouvé quelqu'un d'autre, et il n'a pas insisté.",
                     effects: [FDEffect(attr: .sangfroid, delta: 2), FDEffect(rel: "coach", delta: -3)]),
        ]),
    FDSceneDef(
        id: "lea_discours", category: "Leadership", minAge: 21, maxAge: 36,
        location: "Vestiaire", character: "Le groupe",
        text: "Match le plus important de la saison dans quinze minutes, et le vestiaire est silencieux comme un couloir d'hôpital. Personne ne se parle, personne ne met de musique, tout le monde regarde le sol. Le coach a fini son discours il y a cinq minutes et rien n'a pris.",
        choices: [
            FDChoice(label: "Prendre la parole", hint: "Tu t'es levé et tu as parlé. Court, dur, sans citer personne. Le groupe est sorti transformé.",
                     effects: [FDEffect(attr: .leadership, delta: 5), FDEffect(rel: "vestiaire", delta: 6), FDEffect(cond: "confiance", delta: 4), FDEffect(cond: "moral", delta: -3)]),
            FDChoice(label: "Mettre la musique à fond", hint: "Tu as mis la musique à fond sans dire un mot. Ça a suffi à casser le silence — et ça n'a pas plu à tout le monde.",
                     effects: [FDEffect(rel: "vestiaire", delta: 3), FDEffect(cond: "moral", delta: 3), FDEffect(cond: "fatigue", delta: 6)]),
            FDChoice(label: "Rester dans ta bulle", hint: "Tu es resté dans ta bulle jusqu'au coup d'envoi. Tu as fait un très bon match, et le groupe est entré endormi.",
                     effects: [FDEffect(attr: .sangfroid, delta: 3), FDEffect(cond: "confiance", delta: 2), FDEffect(cond: "fatigue", delta: 6)]),
        ]),
    FDSceneDef(
        id: "lea_erreur_coequipier", category: "Leadership", minAge: 20, maxAge: 36,
        location: "Terrain", character: "Un coéquipier",
        text: "Il a raté son contrôle à trente mètres de son but et l'adversaire a marqué dans la foulée. Le stade entier le siffle, y compris son propre virage. Il est resté au sol trois secondes de trop, et maintenant il marche vers le rond central sans regarder personne.",
        choices: [
            FDChoice(label: "Aller le relever devant tout le monde", hint: "Tu es allé le relever devant tout le monde, en le prenant par le maillot. Le stade a changé de ton en dix secondes.",
                     effects: [FDEffect(attr: .leadership, delta: 4), FDEffect(rel: "vestiaire", delta: 7), FDEffect(rel: "fans", delta: 3), FDEffect(cond: "moral", delta: -3)]),
            FDChoice(label: "L'engueuler pour le réveiller", hint: "Tu l'as engueulé pour le réveiller. Il a réagi, il a été énorme ensuite, et il ne t'a pas parlé du reste du mois.",
                     effects: [FDEffect(attr: .leadership, delta: 2), FDEffect(rel: "vestiaire", delta: -4)]),
            FDChoice(label: "Ne rien faire", hint: "Tu n'as rien fait. Il a coulé pendant quarante-cinq minutes, et le coach l'a sorti à l'heure de jeu.",
                     effects: [FDEffect(rel: "vestiaire", delta: -2)]),
        ]),
    FDSceneDef(
        id: "lea_penalty_responsabilite", category: "Leadership", minAge: 19, maxAge: 36,
        location: "Point de penalty", character: "L'arbitre",
        text: "89e minute, score nul, penalty pour vous. Le tireur habituel est sorti à la 70e, le deuxième sur la liste vient d'entrer et n'a pas touché dix ballons. Le ballon a atterri dans tes mains sans que personne ne le décide. Le stade entier attend de voir qui le pose.",
        choices: [
            FDChoice(label: "Le tirer", hint: "Tu l'as posé et tu l'as tiré. Peu importe le résultat : c'est toi qui as pris le ballon quand il pesait le plus lourd.",
                     effects: [FDEffect(attr: .sangfroid, delta: 4), FDEffect(cond: "confiance", delta: 5), FDEffect(attr: .tir, delta: 2), FDEffect(rel: "vestiaire", delta: -3)]),
            FDChoice(label: "Le donner à un coéquipier", hint: "Tu l'as donné au coéquipier qui le demandait. Il a assumé, et une partie du stade a retenu que tu ne l'avais pas fait.",
                     effects: [FDEffect(rel: "vestiaire", delta: 5), FDEffect(attr: .sangfroid, delta: -1)]),
        ]),
    FDSceneDef(
        id: "lea_mediation_coach", category: "Leadership", minAge: 22, maxAge: 36,
        location: "Couloir du stade", character: "Un coéquipier",
        text: "Trois semaines que le coach et lui ne s'adressent plus la parole, depuis un remplacement mal vécu. Le groupe fait le tampon à chaque séance, les entraînements sont pourris par ça, et personne n'ose aller voir l'un ou l'autre. Toi, tu peux parler aux deux.",
        choices: [
            FDChoice(label: "Organiser une discussion", hint: "Tu as organisé la discussion, dans un bureau, un mardi soir. Vingt minutes pénibles, et une saison sauvée.",
