            FDChoice(label: "Rester en dehors", hint: "Tu es resté en dehors. Le joueur a été écarté du groupe en janvier, et l'ambiance est restée lourde jusqu'à l'été.",
                     effects: [FDEffect(attr: .sangfroid, delta: 1), FDEffect(rel: "vestiaire", delta: -3)]),
        ]),
    FDSceneDef(
        id: "lea_jeune_transfert", category: "Leadership", minAge: 24, maxAge: 36,
        location: "Vestiaire", character: "Un jeune du groupe",
        text: "Il a vingt ans, tu l'as accompagné depuis son arrivée, et un club trois fois plus riche lui propose le triple de son salaire pour un rôle de remplaçant. Il vient te demander conseil dans le vestiaire vide, sincèrement, parce que toi tu n'as rien à y gagner.",
        choices: [
            FDChoice(label: "Lui conseiller de partir", hint: "Tu lui as dit de partir prendre l'argent. Il est parti, il n'a plus joué, et il te dit encore que tu avais tort.",
                     effects: [FDEffect(rel: "vestiaire", delta: 4), FDEffect(attr: .leadership, delta: 3), FDEffect(cond: "moral", delta: -3)]),
            FDChoice(label: "Le convaincre de rester", hint: "Tu l'as convaincu de rester une saison de plus. Il est devenu titulaire, et il est parti trois fois plus cher.",
                     effects: [FDEffect(rel: "president", delta: 5), FDEffect(rel: "vestiaire", delta: 2), FDEffect(cond: "fatigue", delta: 6)]),
            FDChoice(label: "Refuser de répondre", hint: "Tu as refusé de répondre : ce n'est pas ta décision. Il est parti quand même, sans savoir quoi penser de ton silence.",
                     effects: [FDEffect(rel: "vestiaire", delta: -3)]),
        ]),
    FDSceneDef(
        id: "lea_brassard_premiere", category: "Leadership", minAge: 23, maxAge: 36, once: true,
        location: "Tunnel du stade", character: "Entraîneur principal",
        text: "Le capitaine s'est blessé à l'échauffement. Le coach traverse le tunnel avec le brassard à la main, à deux minutes de l'entrée sur le terrain, et il te le tend sans rien expliquer. Vingt joueurs te regardent l'enfiler. Tu ne l'as jamais porté de ta vie.",
        choices: [
            FDChoice(label: "Le porter et haranguer le groupe", hint: "Tu l'as enfilé et tu as haranguer le groupe dans le tunnel, à pleine voix. Le stade a entendu, et le club a trouvé son capitaine.",
                     effects: [FDEffect(attr: .leadership, delta: 6), FDEffect(cond: "confiance", delta: 5), FDEffect(cond: "fatigue", delta: 4)]),
            FDChoice(label: "Le porter sans rien changer", hint: "Tu l'as porté sans rien changer à ta manière de faire. Tu as très bien joué, et le brassard est revenu à son propriétaire lundi.",
                     effects: [FDEffect(attr: .leadership, delta: 2), FDEffect(attr: .sangfroid, delta: 3), FDEffect(cond: "moral", delta: -3)]),
        ]),
    FDSceneDef(
        id: "ves_anniversaire_club", category: "Vestiaire", minAge: 19, maxAge: 35,
        location: "Salle du club", character: "Le staff",
        text: "Le club fête ses cent ans : gala, anciens présidents, familles, télévision locale. On te demande de représenter les joueurs au micro, devant six cents personnes, parce que « c'est toi qu'ils aiment le mieux ». On te prévient trois jours avant.",
        choices: [
            FDChoice(label: "Faire un discours travaillé", hint: "Tu as travaillé ton discours trois soirs et tu l'as fait apprendre par cœur. La salle s'est levée, et le club a une vidéo pour cent ans de plus.",
