            FDChoice(label: "Décliner", hint: "Tu as décliné poliment. Quelqu'un d'autre s'en est chargé, et deux dirigeants ont trouvé ça dommage.",
                     effects: [FDEffect(rel: "president", delta: -4), FDEffect(cond: "moral", delta: 1)]),
        ]),
    FDSceneDef(
        id: "ent_arbitre_entrainement", category: "Entraînement", minAge: 18, maxAge: 34,
        location: "Terrain d'entraînement", character: "Un arbitre invité",
        text: "Le club a fait venir un arbitre de haut niveau pour expliquer les nouvelles règles au groupe. Trois joueurs ricanent depuis le début au fond de la salle et ça s'entend. L'arbitre continue, imperturbable, mais il a compris exactement qui riait.",
        choices: [
            FDChoice(label: "Poser des questions sérieuses", hint: "Tu as posé de vraies questions, sérieusement, pendant vingt minutes. Il t'a expliqué comment se faire écouter par un arbitre — ça t'a servi tout de suite.",
                     effects: [FDEffect(attr: .vision, delta: 2), FDEffect(attr: .sangfroid, delta: 2), FDEffect(rel: "coach", delta: 3), FDEffect(cond: "fatigue", delta: 9)]),
            FDChoice(label: "Rire avec les autres", hint: "Tu as ri avec les autres. La séance s'est terminée vite, et vous avez pris trois cartons évitables cette saison.",
                     effects: [FDEffect(rel: "vestiaire", delta: 3), FDEffect(rel: "coach", delta: -3)]),
        ]),
    FDSceneDef(
        id: "coa_rotation", category: "Coach", minAge: 22, maxAge: 36,
        location: "Bureau du coach", character: "Entraîneur principal",
        text: "Le coach t'annonce sa décision sans que tu aies demandé quoi que ce soit : un match sur deux cette saison, pour préserver un corps qui a trente-trois ans. C'est probablement raisonnable. C'est aussi la première fois qu'on décide de ton temps de jeu à ta place.",
        choices: [
            FDChoice(label: "Accepter la gestion", hint: "Tu as accepté la gestion. Tu as fini la saison entier, et tu as regardé quinze matchs depuis le banc.",
                     effects: [FDEffect(cond: "forme", delta: 6), FDEffect(cond: "fatigue", delta: -10), FDEffect(cond: "confiance", delta: -2)]),
            FDChoice(label: "Refuser et réclamer tous les matchs", hint: "Tu as refusé et réclamé tous les matchs. Tu les as joués, tous — et tu as fini la saison à l'infirmerie.",
                     effects: [FDEffect(cond: "fatigue", delta: 10), FDEffect(rel: "coach", delta: -4), FDEffect(cond: "confiance", delta: 4)]),
        ]),
    FDSceneDef(
        id: "cri_fin_de_cycle", category: "Crise", minAge: 25, maxAge: 36,
        location: "Bureau du directeur sportif", character: "Directeur sportif",
        text: "Le directeur sportif te reçoit sans détour : le club veut rajeunir, ton salaire pèse, et un départ « arrangerait tout le monde ». Il te dit ça poliment, dossier ouvert, avec deux clubs déjà contactés dans le tiroir. Tu as encore un an de contrat.",
        choices: [
            FDChoice(label: "Partir la tête haute", hint: "Tu es parti la tête haute, sans laisser dire n'importe quoi. Le club a communiqué proprement, et tu as rejoué ailleurs.",
                     effects: [FDEffect(rel: "president", delta: 5), FDEffect(rel: "agent", delta: 5), FDEffect(cond: "moral", delta: -3)]),
            FDChoice(label: "Rester et te battre pour ta place", hint: "Tu es resté te battre pour ta place. Six mois durs, un coach qui change d'avis, et une place reprise à la loyale.",
                     effects: [FDEffect(attr: .determination, delta: 5), FDEffect(rel: "president", delta: -5), FDEffect(cond: "fatigue", delta: 6)]),
        ]),
    FDSceneDef(
        id: "ves_cadre_dechu", category: "Vestiaire", minAge: 28, maxAge: 36,
        location: "Vestiaire", character: "Un ancien cadre",
        text: "Il ne joue plus depuis novembre et il pourrit le vestiaire depuis : remarques en réunion, soupirs pendant les séances, deux jeunes déjà cassés en public. Il a été énorme pour ce club pendant huit ans. Le groupe attend que quelqu'un fasse quelque chose, et regarde vers toi.",
        choices: [
            FDChoice(label: "Lui parler seul à seul", hint: "Tu lui as parlé seul à seul, longuement, sans témoin. Il a levé le pied, et il t'a remercié six mois plus tard.",
                     effects: [FDEffect(attr: .leadership, delta: 4), FDEffect(rel: "vestiaire", delta: 4), FDEffect(rel: "capitaine", delta: -3)]),
            FDChoice(label: "Alerter le coach", hint: "Tu as alerté le coach. Il a été écarté du groupe en deux semaines, et le vestiaire a su qui avait parlé.",
                     effects: [FDEffect(rel: "coach", delta: 5), FDEffect(rel: "vestiaire", delta: -6)]),
            FDChoice(label: "Ignorer", hint: "Tu as ignoré. Deux jeunes ont demandé à partir en janvier.",
                     effects: [FDEffect(rel: "vestiaire", delta: -2)]),
        ]),
    FDSceneDef(
        id: "ent_hiver", category: "Entraînement", minAge: 16, maxAge: 36,
        location: "Terrain gelé", character: "Entraîneur principal",
        text: "Moins cinq degrés, terrain gelé par plaques, et le coach maintient la séance dehors. Le groupe est sorti en traînant, les mains dans les manches, personne ne veut toucher le premier ballon. L'échauffement commence dans deux minutes et tout le monde attend de voir.",
        choices: [
