                     effects: [FDEffect(rel: "president", delta: 6), FDEffect(cond: "reputation", delta: -4), FDEffect(cond: "fatigue", delta: -6)]),
        ]),
    FDSceneDef(
        id: "sel_capitaine_nation", category: "Sélection", minAge: 24, maxAge: 36,
        location: "Centre national", character: "Sélectionneur",
        text: "Le sélectionneur t'annonce qu'il pense à toi pour le brassard national : ce n'est pas encore fait, mais il veut savoir si tu le prendrais. Le capitaine actuel a trente-quatre ans et joue de moins en moins. Le pays entier commentera la décision pendant une semaine.",
        choices: [
            FDChoice(label: "Accepter la responsabilité", hint: "Tu as accepté la responsabilité. Tu représentes un pays entier maintenant, et chacune de tes phrases pèse dix fois plus.",
                     effects: [FDEffect(attr: .leadership, delta: 6), FDEffect(cond: "reputation", delta: 6), FDEffect(cond: "fatigue", delta: 4)]),
            FDChoice(label: "Décliner, trop tôt", hint: "Tu as décliné en disant que c'était trop tôt. Il a apprécié l'honnêteté, et il a donné le brassard à un autre.",
                     effects: [FDEffect(attr: .sangfroid, delta: 2), FDEffect(rel: "coach", delta: -3)]),
        ]),
    FDSceneDef(
        id: "sel_elimination", category: "Sélection", minAge: 20, maxAge: 36,
        location: "Vestiaire de la sélection", character: "Le groupe",
        text: "Éliminés en phase de groupes, avion du retour dans quatre heures, et le pays cherche un responsable depuis le coup de sifflet final. Ton nom revient dans toutes les émissions. Le service de presse conseille à tout le monde de ne rien dire en zone mixte.",
        choices: [
            FDChoice(label: "Assumer devant la presse", hint: "Tu as assumé devant les caméras, seul, pendant que les autres passaient sans s'arrêter. Le pays s'est un peu calmé, et tu as tout pris.",
                     effects: [FDEffect(cond: "reputation", delta: 5), FDEffect(rel: "media", delta: 5), FDEffect(cond: "moral", delta: -4)]),
            FDChoice(label: "Te taire", hint: "Tu t'es tu, comme les autres. La polémique a duré trois semaines de plus.",
                     effects: [FDEffect(cond: "moral", delta: -2), FDEffect(rel: "media", delta: -3)]),
        ]),
    FDSceneDef(
        id: "sel_double_nationalite", category: "Sélection", minAge: 17, maxAge: 27, once: true,
        location: "Salon familial", character: "Un émissaire fédéral",
        text: "Deux fédérations te veulent, et les deux émissaires ont fait le déplacement jusqu'au salon de tes parents, à deux jours d'intervalle. D'un côté le pays de ta famille, celui des dimanches et de la langue. De l'autre celui où tu es né, où tu as tout appris. Il faut trancher.",
        choices: [
            FDChoice(label: "Choisir le pays de ta famille", hint: "Tu as choisi le pays de ta famille. Ton père a pleuré, et l'autre fédération a parlé d'ingratitude pendant un mois.",
                     effects: [FDEffect(rel: "famille", delta: 10), FDEffect(cond: "reputation", delta: 3), FDEffect(rel: "coach", delta: -3)]),
            FDChoice(label: "Choisir le pays où tu as grandi", hint: "Tu as choisi le pays où tu as grandi. C'était le choix logique, et le repas de famille suivant a été très silencieux.",
                     effects: [FDEffect(cond: "reputation", delta: 5), FDEffect(rel: "famille", delta: -5), FDEffect(rel: "fans", delta: 4)]),
        ]),
    FDSceneDef(
        id: "sel_amical_lointain", category: "Sélection", minAge: 19, maxAge: 36,
        location: "Aéroport", character: "Sélectionneur",
        text: "Deux amicaux à l'autre bout du monde, en plein hiver, au milieu de ta saison : vingt-quatre heures d'avion aller-retour pour cent quatre-vingts minutes qui ne comptent pour rien. Ton club ne dit rien officiellement, et ton kiné t'a regardé sans rien dire non plus.",
        choices: [
            FDChoice(label: "Y aller", hint: "Tu y es allé. Tu as joué les deux matchs, et tu es rentré décalé pour trois semaines.",
                     effects: [FDEffect(cond: "fatigue", delta: 14), FDEffect(cond: "reputation", delta: 4), FDEffect(rel: "coach", delta: -3)]),
            FDChoice(label: "Invoquer une gêne musculaire", hint: "Tu as invoqué une gêne musculaire. Le sélectionneur n'a rien dit, et il a noté que tu n'étais pas venu.",
                     effects: [FDEffect(cond: "fatigue", delta: -4), FDEffect(cond: "reputation", delta: -5)]),
        ]),
    FDSceneDef(
        id: "sel_finale_continentale", category: "Sélection", minAge: 21, maxAge: 36,
        location: "Vestiaire", character: "Sélectionneur",
        text: "Finale continentale. Le pays est à l'arrêt depuis midi, les écrans géants sont pleins jusque dans ta rue, et le sélectionneur a fini son discours il y a deux minutes. Tu joues le match d'une vie dans un quart d'heure, et tu le sais en enfilant ton maillot.",
        choices: [
            FDChoice(label: "Prendre le jeu à ton compte", hint: "Tu as pris le jeu à ton compte, du début à la fin. Quatre-vingt-dix minutes où tout est passé par toi, et un pays qui s'en souviendra.",
                     effects: [FDEffect(attr: .dribble, delta: 2), FDEffect(attr: .tir, delta: 2), FDEffect(cond: "fatigue", delta: 10)]),
            FDChoice(label: "Jouer pour le collectif", hint: "Tu as tout mis au service du collectif, sans chercher la lumière. Le trophée compte plus que les images.",
                     effects: [FDEffect(attr: .vision, delta: 3), FDEffect(rel: "vestiaire", delta: 6), FDEffect(cond: "fatigue", delta: 9)]),
        ]),
    FDSceneDef(
        id: "dec_dernier_ballon", category: "Moment décisif", minAge: 18, maxAge: 36,
        location: "Surface adverse", character: "Le temps additionnel",
        text: "Dernière seconde du temps additionnel, ballon dans la surface, un défenseur au marquage dans ton dos et un coéquipier complètement seul sur ta gauche. Le gardien a fait un pas. Tu as le temps d'un contrôle, pas de deux, et le stade entier est debout.",
        choices: [
            FDChoice(label: "Frapper", hint: "Tu as frappé. La postérité tenait dans ce ballon, et tout le monde a retenu que c'est toi qui l'avais pris.",
                     effects: [FDEffect(attr: .tir, delta: 3), FDEffect(cond: "confiance", delta: 4), FDEffect(cond: "fatigue", delta: 6)]),
            FDChoice(label: "Servir le coéquipier", hint: "Tu l'as servi sur la gauche, au dernier moment. Il avait le but ouvert, et le stade a compris qui avait fait l'action.",
                     effects: [FDEffect(attr: .vision, delta: 3), FDEffect(rel: "vestiaire", delta: 5), FDEffect(cond: "confiance", delta: -3)]),
        ]),
    FDSceneDef(
        id: "dec_main_surface", category: "Moment décisif", minAge: 18, maxAge: 36,
        location: "Surface", character: "L'arbitre",
        text: "Le ballon t'a touché la main avant de rentrer — franchement, sans discussion possible. L'arbitre n'a rien vu, il a désigné le rond central, et tes coéquipiers sont déjà sur toi. Il n'y a pas d'assistance vidéo dans cette compétition. Tu es le seul à savoir.",
        choices: [
            FDChoice(label: "Le signaler", hint: "Tu l'as signalé à l'arbitre. Le but a été annulé, ton camp ne l'a pas compris, et le monde entier en a parlé pendant trois jours.",
                     effects: [FDEffect(cond: "reputation", delta: 10), FDEffect(rel: "fans", delta: -4), FDEffect(rel: "vestiaire", delta: -4)]),
            FDChoice(label: "Ne rien dire", hint: "Tu n'as rien dit. Le but a compté, vous avez gagné, et tu y penses encore parfois.",
                     effects: [FDEffect(cond: "confiance", delta: 3), FDEffect(cond: "reputation", delta: -3)]),
        ]),
    FDSceneDef(
        id: "dec_simulation", category: "Moment décisif", minAge: 18, maxAge: 36,
        location: "Surface adverse", character: "Le défenseur",
        text: "88e minute, score nul, tu entres dans la surface et le défenseur pose une main dans ton dos — léger, insuffisant, mais suffisant pour tomber si tu le décides. L'arbitre est bien placé et hésite déjà. Tout le stade a vu le contact.",
        choices: [
            FDChoice(label: "Rester debout", hint: "Tu es resté debout et tu as frappé en déséquilibre. Le geste a été salué partout — et vous n'avez pas eu le penalty.",
                     effects: [FDEffect(cond: "reputation", delta: 6), FDEffect(attr: .sangfroid, delta: 3), FDEffect(cond: "fatigue", delta: 6)]),
            FDChoice(label: "Tomber", hint: "Tu es tombé. Penalty accordé, victoire au bout, et les images ont tourné pendant une semaine.",
                     effects: [FDEffect(cond: "reputation", delta: -6), FDEffect(cond: "confiance", delta: 3), FDEffect(rel: "fans", delta: 2)]),
        ]),
    FDSceneDef(
        id: "dec_blessure_adversaire", category: "Moment décisif", minAge: 18, maxAge: 36,
        location: "Terrain", character: "Un adversaire au sol",
        text: "Un adversaire est resté au sol au milieu du terrain, immobile, la main sur la tête. Le ballon traîne à tes pieds, tu es lancé, il n'y a plus personne devant toi jusqu'au but. Son banc hurle de mettre en touche. Le tien hurle exactement le contraire.",
        choices: [
            FDChoice(label: "Mettre le ballon en touche", hint: "Tu as mis le ballon en touche. Le stade adverse t'a applaudi, et ton coach t'a passé un savon à la mi-temps.",
                     effects: [FDEffect(cond: "reputation", delta: 8), FDEffect(rel: "fans", delta: 5), FDEffect(rel: "coach", delta: -3)]),
            FDChoice(label: "Aller au bout de l'action", hint: "Tu es allé au bout de l'action et tu as marqué. Le but compte, et le match s'est terminé dans une bagarre générale.",
                     effects: [FDEffect(attr: .tir, delta: 2), FDEffect(cond: "reputation", delta: -6)]),
        ]),
    FDSceneDef(
        id: "dec_but_annule", category: "Moment décisif", minAge: 18, maxAge: 36,
        location: "Terrain", character: "L'arbitre assistant",
        text: "Ton but est annulé pour quelques centimètres, après quarante secondes d'attente et un trait tracé à l'écran. Le stade était en train de célébrer. Le silence qui suit est le plus long que tu aies entendu. Il reste huit minutes à jouer.",
        choices: [
            FDChoice(label: "Repartir immédiatement au combat", hint: "Tu es reparti immédiatement au combat, sans un regard vers l'écran. Tu as été décisif dans les huit minutes.",
                     effects: [FDEffect(attr: .determination, delta: 4), FDEffect(cond: "fatigue", delta: 6)]),
            FDChoice(label: "Perdre tes moyens", hint: "Tu as perdu tes moyens. Tu as raté les trois ballons suivants, et le coach t'a sorti.",
                     effects: [FDEffect(cond: "confiance", delta: -5), FDEffect(cond: "moral", delta: -4)]),
        ]),
    FDSceneDef(
        id: "dec_carton_rouge", category: "Moment décisif", minAge: 18, maxAge: 36,
        location: "Terrain", character: "L'arbitre",
        text: "Rouge direct, demi-heure de jeu, match capital : tacle en retard sur un joueur lancé, semelle haute, aucune discussion possible. L'arbitre n'a même pas hésité. Tes coéquipiers vont jouer une heure à dix, et le vestiaire est très loin.",
        choices: [
            FDChoice(label: "Sortir sans protester", hint: "Tu es sorti sans protester, tête basse, en applaudissant tes coéquipiers. La commission a été clémente.",
                     effects: [FDEffect(attr: .sangfroid, delta: 3), FDEffect(rel: "coach", delta: 2), FDEffect(cond: "confiance", delta: -3)]),
            FDChoice(label: "Contester longuement", hint: "Tu as contesté pendant deux minutes, jusqu'à ce qu'on vienne te chercher. Un match de suspension en plus, et une amende.",
                     effects: [FDEffect(cond: "reputation", delta: -5), FDEffect(rel: "coach", delta: -4)]),
        ]),
    FDSceneDef(
        id: "dec_penalty_arret", category: "Moment décisif", minAge: 18, maxAge: 36,
        location: "Ligne de but", character: "Le tireur adverse",
        text: "Arrêts de jeu, penalty contre toi, et tout le monde dans le stade sait que c'est la dernière action. Tes défenseurs se sont éloignés jusqu'au rond central. Le tireur pose le ballon, recule de six pas, et te regarde. Tu as trois secondes pour choisir ta lecture.",
        choices: [
            FDChoice(label: "Plonger tôt d'un côté", hint: "Tu es parti tôt d'un côté, à l'instinct. Il a tiré au milieu, ou dans tes mains — tout se joue sur ce genre de pari.",
                     effects: [FDEffect(attr: .agilite, delta: 3), FDEffect(cond: "confiance", delta: 4), FDEffect(cond: "reputation", delta: -3)]),
            FDChoice(label: "Attendre la dernière fraction de seconde", hint: "Tu as attendu la toute dernière fraction de seconde. Tu es parti après le ballon, et tu l'as touché.",
                     effects: [FDEffect(attr: .sangfroid, delta: 4), FDEffect(attr: .placement, delta: 2), FDEffect(cond: "reputation", delta: -3)]),
        ],
        positions: [.gardien]),
    FDSceneDef(
        id: "dec_sortie_aerienne", category: "Moment décisif", minAge: 18, maxAge: 36,
        location: "Surface", character: "Un attaquant adverse",
        text: "Corner à la dernière minute, 1-1, leur gardien est monté. Le ballon est haut et pend au premier poteau, au milieu de dix-huit joueurs, et leur attaquant arrive lancé dans ta trajectoire sans aucune intention de freiner. Tu as une demi-seconde pour décider.",
        choices: [
            FDChoice(label: "Sortir au poing", hint: "Tu es sorti au poing, dans les corps. Tu as pris un coude, tu as dégagé le ballon à vingt mètres, et le match était fini.",
                     effects: [FDEffect(attr: .force, delta: 2), FDEffect(attr: .agilite, delta: 2), FDEffect(cond: "confiance", delta: 3), FDEffect(cond: "reputation", delta: -3)]),
            FDChoice(label: "Rester sur ta ligne", hint: "Tu es resté sur ta ligne. La reprise est passée à côté — ou dedans, et tu as regardé la trajectoire jusqu'au bout.",
                     effects: [FDEffect(attr: .placement, delta: 3), FDEffect(attr: .sangfroid, delta: 2), FDEffect(cond: "confiance", delta: -3)]),
        ],
        positions: [.gardien]),
    FDSceneDef(
        id: "dec_tacle_dernier_defenseur", category: "Moment décisif", minAge: 18, maxAge: 36,
        location: "Trente mètres du but", character: "Un attaquant adverse",
        text: "Il te prend de vitesse à trente mètres du but, tu es le dernier défenseur, et le gardien est avancé. Tu as encore une foulée pour l'accrocher — carton rouge assuré, mais l'occasion tuée. Ou tu tentes de revenir sur lui, et il te reste peut-être deux mètres à combler.",
        choices: [
            FDChoice(label: "Faire faute", hint: "Tu as fait faute. Rouge, suspension, et une équipe à dix — mais pas de but encaissé sur cette action-là.",
                     effects: [FDEffect(attr: .tacle, delta: 2), FDEffect(cond: "reputation", delta: -3), FDEffect(rel: "vestiaire", delta: 4)]),
            FDChoice(label: "Tenter de le rattraper", hint: "Tu as tenté de le rattraper, à fond. Tu l'as rejoint au moment de sa frappe, et tu as touché le ballon.",
                     effects: [FDEffect(attr: .vitesse, delta: 3), FDEffect(cond: "fatigue", delta: 6)]),
        ],
        positions: [.defenseur]),
    FDSceneDef(
        id: "dec_relance_risquee", category: "Moment décisif", minAge: 18, maxAge: 36,
        location: "Ta propre surface", character: "Un attaquant adverse",
        text: "Ils pressent à quatre dans ta surface, 1-0 pour vous, dix minutes à tenir. Ton défenseur central s'ouvre à six mètres, dos au but, avec un attaquant dans les jambes. Le coach hurle de jouer court depuis le début du match. Le stade hurle exactement l'inverse.",
        choices: [
            FDChoice(label: "Jouer court sous pression", hint: "Tu as joué court sous la pression. Une frayeur de deux secondes, et un ballon ressorti proprement.",
                     effects: [FDEffect(attr: .passe, delta: 3), FDEffect(attr: .sangfroid, delta: 3), FDEffect(cond: "confiance", delta: -1)]),
            FDChoice(label: "Dégager en touche", hint: "Tu as dégagé en touche, loin. Le stade a soufflé, le coach a levé les bras au ciel.",
                     effects: [FDEffect(attr: .force, delta: 1), FDEffect(rel: "coach", delta: -2)]),
        ]),
    FDSceneDef(
        id: "dec_dribble_de_trop", category: "Moment décisif", minAge: 18, maxAge: 36,
        location: "Aile gauche", character: "Le banc adverse",
        text: "Tu as déjà éliminé deux défenseurs sur cette action, le stade est debout, et un troisième arrive en glissant. Ton coéquipier est seul au deuxième poteau depuis trois secondes et hurle. Tu as le geste dans les jambes — tu l'as fait cent fois à l'entraînement.",
        choices: [
            FDChoice(label: "Tenter le troisième dribble", hint: "Tu as tenté le troisième. Soit c'est l'action de ta saison, soit le contre part de là — et le banc s'en souvient longtemps.",
                     effects: [FDEffect(attr: .dribble, delta: 3), FDEffect(rel: "vestiaire", delta: -3), FDEffect(cond: "confiance", delta: 3)]),
            FDChoice(label: "Servir simple", hint: "Tu as servi simple au deuxième poteau. But facile, et personne ne parlera de ton action.",
                     effects: [FDEffect(attr: .passe, delta: 2), FDEffect(rel: "vestiaire", delta: 5), FDEffect(rel: "coach", delta: 3), FDEffect(cond: "fatigue", delta: 6)]),
        ]),
    FDSceneDef(
        id: "mat_serie_defaites", category: "Match important", minAge: 18, maxAge: 36,
        location: "Vestiaire", character: "Le groupe",
        text: "Cinquième défaite d'affilée. Le vestiaire ne se regarde plus, deux joueurs sont partis sans se doucher, et le staff s'est enfermé dans son bureau. Personne ne dit rien depuis vingt minutes. Le prochain match est un déplacement chez le leader.",
        choices: [
            FDChoice(label: "Provoquer une réunion sans le staff", hint: "Tu as provoqué une réunion sans le staff, portes fermées. Ça a crié pendant une heure, et le vestiaire est ressorti debout.",
                     effects: [FDEffect(attr: .leadership, delta: 5), FDEffect(rel: "vestiaire", delta: 6), FDEffect(rel: "coach", delta: -2)]),
