        id: "res_video_virale", category: "Réseaux", minAge: 17, maxAge: 32,
        location: "Téléphone", character: "Ton attaché de presse",
        text: "Un geste à l'entraînement, filmé par le community manager du club, publié à dix-huit heures. À minuit, la vidéo est reprise par des comptes internationaux, des joueurs que tu admires ont réagi, et le compteur ne s'arrête plus. Tu as un match dans trois jours.",
        choices: [
            FDChoice(label: "Surfer dessus", hint: "Tu as surfé dessus toute la semaine : republications, réponses, une deuxième vidéo. Ton audience a doublé, et le staff a trouvé ça long.",
                     effects: [FDEffect(cond: "reputation", delta: 6), FDEffect(rel: "media", delta: 5), FDEffect(rel: "vestiaire", delta: -2)]),
            FDChoice(label: "Rester discret", hint: "Tu es resté discret et tu n'as rien republié. La vague est passée, et le respect du vestiaire est resté.",
                     effects: [FDEffect(attr: .sangfroid, delta: 3), FDEffect(rel: "vestiaire", delta: 3), FDEffect(cond: "reputation", delta: -3)]),
        ]),
    FDSceneDef(
        id: "res_polemique_like", category: "Réseaux", minAge: 18, maxAge: 32,
        location: "Téléphone", character: "Ton agent",
        text: "Tu as liké un message polémique à deux heures du matin, en faisant défiler sans lire. Le like a été retiré en quatre minutes. Les captures d'écran, elles, circulaient déjà depuis trois. Ton agent t'appelle à sept heures : c'est repris par deux médias nationaux.",
        choices: [
            FDChoice(label: "T'expliquer clairement", hint: "Tu t'es expliqué clairement, en assumant l'erreur. C'est retombé en quarante-huit heures.",
                     effects: [FDEffect(cond: "reputation", delta: 3), FDEffect(rel: "media", delta: 3), FDEffect(cond: "moral", delta: -3)]),
            FDChoice(label: "Supprimer et se taire", hint: "Tu as supprimé et tu t'es tu. Le silence a été interprété comme un aveu pendant deux semaines.",
                     effects: [FDEffect(cond: "reputation", delta: -4)]),
        ]),
    FDSceneDef(
        id: "res_live", category: "Réseaux", minAge: 18, maxAge: 30,
        location: "Chambre", character: "Tes abonnés",
        text: "Minuit passé, victoire dans un match capital, et tu lances un live depuis ta chambre sans trop réfléchir. Cent mille personnes arrivent en quatre minutes. Les questions défilent, certaines sur le coach, d'autres sur un coéquipier. Tu as encore l'adrénaline du match.",
        choices: [
            FDChoice(label: "Parler du match sans filtre", hint: "Tu as parlé du match sans filtre pendant quarante minutes. Deux phrases ont fait la une le lendemain matin.",
                     effects: [FDEffect(rel: "media", delta: 5), FDEffect(rel: "vestiaire", delta: -4), FDEffect(cond: "reputation", delta: 4)]),
            FDChoice(label: "Couper au bout de dix minutes", hint: "Tu as coupé au bout de dix minutes, avant de dire une bêtise. Les abonnés ont râlé, ton agent a soufflé.",
                     effects: [FDEffect(attr: .sangfroid, delta: 2), FDEffect(cond: "fatigue", delta: 3)]),
        ]),
    FDSceneDef(
        id: "res_challenge", category: "Réseaux", minAge: 17, maxAge: 30,
        location: "Terrain d'entraînement", character: "Un influenceur",
        text: "Un influenceur suivi par des millions de personnes te défie sur un concours de frappes, filmé, au centre d'entraînement. Le club trouve l'idée excellente pour l'image. Il s'entraîne à ça toute la journée depuis trois ans, et toi tu sors d'une double séance.",
        choices: [
            FDChoice(label: "Accepter et gagner", hint: "Tu as accepté et tu l'as battu. La vidéo a fait vingt millions de vues, et le club t'a remercié.",
                     effects: [FDEffect(cond: "reputation", delta: 5), FDEffect(attr: .tir, delta: 2), FDEffect(rel: "coach", delta: -2)]),
            FDChoice(label: "Refuser", hint: "Tu as refusé le défi. Personne ne t'a rien reproché — sauf le service communication du club.",
                     effects: [FDEffect(attr: .sangfroid, delta: 2), FDEffect(cond: "reputation", delta: -3)]),
        ]),
    FDSceneDef(
        id: "res_message_prive", category: "Réseaux", minAge: 18, maxAge: 30,
        location: "Téléphone", character: "Un jeune supporter",
        text: "Un message parmi des milliers, envoyé à trois heures du matin par un compte sans photo. Un gamin explique qu'il pense à tout arrêter, que rien ne va, et que tes matchs sont la seule chose qu'il attend dans la semaine. Il ne demande rien. Tu l'as lu deux fois.",
        choices: [
            FDChoice(label: "Lui répondre longuement", hint: "Tu lui as répondu longuement, personnellement, et vous avez échangé pendant des mois. Il va mieux.",
                     effects: [FDEffect(cond: "moral", delta: 8), FDEffect(cond: "reputation", delta: 4), FDEffect(cond: "fatigue", delta: 2)]),
            FDChoice(label: "Le faire inviter au prochain match", hint: "Tu l'as fait inviter au prochain match, en tribune, avec un maillot. Il est venu, il n'a pas réussi à parler, et il a tout gardé.",
                     effects: [FDEffect(money: -2000, delta: 0), FDEffect(rel: "fans", delta: 8), FDEffect(cond: "moral", delta: 6)]),
            FDChoice(label: "Ne pas répondre", hint: "Tu n'as pas répondu. Le message est resté ouvert dans tes messages non lus pendant des mois.",
                     effects: [FDEffect(cond: "moral", delta: -5)]),
        ]),
    FDSceneDef(
        id: "sup_tifo", category: "Supporters", minAge: 19, maxAge: 36,
        location: "Tribune", character: "Chef de tribune",
        text: "Le chef de tribune te prévient : les ultras préparent un tifo de vingt mètres à ton effigie pour le prochain match. Ils y travaillent depuis six semaines dans un hangar, ils ont fait une cagnotte, et ils te demandent seulement de ne rien dire avant le coup d'envoi.",
        choices: [
            FDChoice(label: "Aller les remercier après le match", hint: "Tu es allé les remercier après le match, sous le virage, longuement. Ils en parlent encore.",
                     effects: [FDEffect(rel: "fans", delta: 10), FDEffect(cond: "moral", delta: 6), FDEffect(cond: "fatigue", delta: 5)]),
            FDChoice(label: "Ne pas réagir", hint: "Tu n'as pas réagi, ni pendant ni après. Le tifo est resté magnifique, et le virage a trouvé ça froid.",
                     effects: [FDEffect(rel: "fans", delta: -3)]),
        ]),
    FDSceneDef(
        id: "sup_reunion_ultras", category: "Supporters", minAge: 19, maxAge: 36,
        location: "Local des ultras", character: "Chef de tribune",
        text: "Après six matchs sans victoire, les ultras convoquent les joueurs dans leur local, un mardi soir. Ce n'est pas une invitation. La moitié du vestiaire refuse d'y aller, le club conseille officiellement de ne pas s'y rendre, et ils attendent à partir de vingt heures.",
        choices: [
            FDChoice(label: "Y aller", hint: "Tu y es allé. Deux heures de discussion très dure, sans casse, et un virage qui t'a soutenu jusqu'au bout de la saison.",
                     effects: [FDEffect(rel: "fans", delta: 8), FDEffect(cond: "reputation", delta: 4), FDEffect(rel: "vestiaire", delta: 2), FDEffect(cond: "fatigue", delta: 5)]),
            FDChoice(label: "Refuser d'y aller", hint: "Tu n'y es pas allé, comme le club le conseillait. Le virage a affiché les noms des absents la semaine suivante.",
                     effects: [FDEffect(rel: "fans", delta: -8), FDEffect(attr: .sangfroid, delta: 2)]),
        ]),
    FDSceneDef(
        id: "sup_maillot_brule", category: "Supporters", minAge: 20, maxAge: 36,
        location: "Parking du stade", character: "Supporters en colère",
        text: "Une phrase sortie de son contexte, et ce matin des supporters brûlent ton maillot devant le stade, en direct sur les réseaux. Ils sont une trentaine. Le club a mis un communiqué en préparation. Ta famille a vu les images avant toi.",
        choices: [
            FDChoice(label: "Aller t'expliquer sur place", hint: "Tu es allé t'expliquer sur place, seul, sans service de sécurité. La discussion a duré une heure et les images ont changé de sens.",
                     effects: [FDEffect(rel: "fans", delta: 8), FDEffect(cond: "reputation", delta: 5), FDEffect(cond: "moral", delta: -3)]),
            FDChoice(label: "Publier un communiqué", hint: "Tu as publié un communiqué écrit par le club. Correct, tiède, et personne n'a changé d'avis.",
                     effects: [FDEffect(rel: "media", delta: 3), FDEffect(rel: "fans", delta: 2), FDEffect(cond: "moral", delta: -2)]),
            FDChoice(label: "Ne rien faire", hint: "Tu n'as rien fait. Ça s'est calmé en trois semaines, et le virage ne t'a plus jamais chanté.",
                     effects: [FDEffect(rel: "fans", delta: -8), FDEffect(cond: "moral", delta: -5)]),
        ]),
    FDSceneDef(
        id: "sup_enfant_hopital", category: "Supporters", minAge: 20, maxAge: 36,
        location: "Hôpital", character: "Une famille de supporters",
        text: "Une famille de supporters écrit au club : leur fils de onze ans est opéré vendredi, l'issue est incertaine, et il demande à te voir avant. L'hôpital est à quatre-vingts kilomètres, tu as entraînement matin et après-midi toute la semaine, et l'opération est dans trois jours.",
        choices: [
            FDChoice(label: "Y aller entre deux entraînements", hint: "Tu y es allé entre deux séances, sans prévenir personne. Vous avez parlé une heure, et il est entré au bloc avec ton maillot.",
                     effects: [FDEffect(cond: "moral", delta: 8), FDEffect(rel: "fans", delta: 8), FDEffect(cond: "fatigue", delta: 4)]),
            FDChoice(label: "Envoyer un maillot dédicacé", hint: "Tu as envoyé un maillot dédicacé et une vidéo. Ils ont remercié mille fois, et tu penses encore que tu aurais pu faire le trajet.",
                     effects: [FDEffect(rel: "fans", delta: 3), FDEffect(cond: "moral", delta: 2), FDEffect(cond: "fatigue", delta: 5)]),
        ]),
    FDSceneDef(
        id: "sup_deplacement_lointain", category: "Supporters", minAge: 19, maxAge: 36,
        location: "Parking d'un stade adverse", character: "Supporters déplacés",
        text: "Mille kilomètres à l'aller, un 4-0 dans la figure, mille kilomètres à faire en sens inverse cette nuit. Ils sont deux cents dans le parcage, ils chantent encore, et ils attendent que quelqu'un vienne. Le bus part dans dix minutes et le staff a dit de ne pas traîner.",
        choices: [
            FDChoice(label: "Aller les saluer et t'excuser", hint: "Tu es allé les saluer et t'excuser, maillot à la main. Le parcage s'est tu, puis a chanté ton nom.",
                     effects: [FDEffect(rel: "fans", delta: 10), FDEffect(cond: "reputation", delta: 5), FDEffect(cond: "moral", delta: -2)]),
            FDChoice(label: "Filer au bus", hint: "Tu as filé au bus avec les autres. Ils ont chanté quand même, et ils ont retenu qui n'était pas venu.",
                     effects: [FDEffect(rel: "fans", delta: -8)]),
        ]),
    FDSceneDef(
        id: "sup_chant_personnel", category: "Supporters", minAge: 20, maxAge: 36,
        location: "Tribune", character: "Le kop",
        text: "Le kop a créé un chant à ton nom, sur un air connu, et le lance à chaque fois que tu touches le ballon. Ça a commencé il y a trois matchs. Aujourd'hui, le stade entier le reprend. Tu l'entends très distinctement pendant que tu essaies de te concentrer.",
        choices: [
            FDChoice(label: "Le saluer à chaque fois", hint: "Tu les salues à chaque fois, poing levé. Le stade adore, et tu joues porté par ça.",
                     effects: [FDEffect(rel: "fans", delta: 8), FDEffect(cond: "confiance", delta: 5), FDEffect(cond: "moral", delta: -2)]),
            FDChoice(label: "Rester concentré", hint: "Tu es resté concentré sur le jeu, sans un geste. Le chant a continué, un peu moins fort.",
                     effects: [FDEffect(attr: .sangfroid, delta: 3), FDEffect(rel: "fans", delta: 1), FDEffect(cond: "fatigue", delta: 5)]),
        ]),
    FDSceneDef(
        id: "sup_critique_ancien", category: "Supporters", minAge: 22, maxAge: 36,
        location: "Plateau télé", character: "Un ancien joueur du club",
        text: "Une légende du club — statue devant le stade, trois cents matchs — te descend en direct sur un plateau : technique insuffisante, mentalité de la nouvelle génération, tout y passe. Le club ne peut rien dire contre lui. Ton téléphone n'a pas arrêté depuis la fin de l'émission.",
        choices: [
            FDChoice(label: "Lui répondre avec respect", hint: "Tu lui as répondu avec respect, en saluant sa carrière avant de défendre la tienne. Tout le monde a trouvé la réponse juste.",
                     effects: [FDEffect(cond: "reputation", delta: 5), FDEffect(rel: "media", delta: 4), FDEffect(cond: "fatigue", delta: 5)]),
            FDChoice(label: "Le contredire frontalement", hint: "Tu l'as contredit frontalement. Le débat a occupé la ville trois semaines, et une partie du stade a pris son parti.",
                     effects: [FDEffect(rel: "media", delta: 5), FDEffect(rel: "fans", delta: -5), FDEffect(cond: "confiance", delta: 3)]),
            FDChoice(label: "Demander à le rencontrer", hint: "Tu as demandé à le rencontrer, en privé. Vous avez déjeuné, et il a nuancé son propos à l'antenne suivante.",
                     effects: [FDEffect(cond: "reputation", delta: 6), FDEffect(rel: "fans", delta: 4), FDEffect(cond: "moral", delta: -2)]),
        ]),
    FDSceneDef(
        id: "riv_nouveau_venu", category: "Rivalité", minAge: 18, maxAge: 32,
        location: "Terrain d'entraînement", character: "Une recrue à ton poste",
        text: "La recrue à ton poste distribue les piques dans chaque interview depuis son arrivée : sur la concurrence, sur le niveau, sur ce qu'il vient chercher. Il n'a pas encore joué une minute. Le vestiaire commente, la presse relance, et le coach n'a rien dit.",
        choices: [
            FDChoice(label: "Répondre par les performances", hint: "Tu as répondu uniquement par tes performances. Trois mois plus tard, il ne parlait plus à personne.",
                     effects: [FDEffect(attr: .determination, delta: 4), FDEffect(cond: "fatigue", delta: 6)]),
            FDChoice(label: "Répondre dans la presse", hint: "Tu as répondu dans la presse. La guerre a duré la saison, et le coach a fini par en écarter un des deux.",
                     effects: [FDEffect(rel: "media", delta: 4), FDEffect(rel: "vestiaire", delta: -4)]),
            FDChoice(label: "Aller lui parler en face", hint: "Tu es allé lui parler en face, dans le vestiaire. Il n'y était pas préparé, et les piques ont cessé.",
                     effects: [FDEffect(attr: .leadership, delta: 4), FDEffect(rel: "vestiaire", delta: 3), FDEffect(cond: "moral", delta: -3)]),
        ]),
    FDSceneDef(
        id: "riv_duel_stats", category: "Rivalité", minAge: 19, maxAge: 34,
        location: "Salle vidéo", character: "Analyste vidéo",
        text: "L'analyste projette la comparaison sur l'écran, sans y mettre de malice : ton rival a deux buts et quatre passes de plus que toi cette saison, à temps de jeu égal. Les colonnes sont côte à côte, en grand, et tu es le seul dans la pièce à ne pas regarder ailleurs.",
        choices: [
            FDChoice(label: "En faire un moteur", hint: "Tu en as fait un moteur. Tu as passé la fin de saison à courir après ces deux buts — et tu les as repris.",
                     effects: [FDEffect(attr: .determination, delta: 4), FDEffect(attr: .tir, delta: 2), FDEffect(cond: "fatigue", delta: 6)]),
            FDChoice(label: "Refuser de comparer", hint: "Tu as refusé de te comparer, et tu l'as dit. Sain, sincère, et l'écart s'est creusé.",
                     effects: [FDEffect(attr: .sangfroid, delta: 4), FDEffect(cond: "moral", delta: 2), FDEffect(rel: "vestiaire", delta: -3)]),
        ]),
    FDSceneDef(
        id: "riv_selection_place", category: "Rivalité", minAge: 20, maxAge: 34,
        location: "Centre national", character: "Un concurrent en sélection",
        text: "Le titulaire à ton poste en sélection s'est blessé pour deux mois. Le sélectionneur t'a convoqué, tu as trois matchs pour lui prendre sa place définitivement. Il sera en tribune pour les trois, en rééducation, et il regardera chacun de tes ballons.",
        choices: [
            FDChoice(label: "Tout donner", hint: "Tu as tout donné sur les trois matchs, jusqu'au surrégime. Deux matchs énormes, un raté — et la place est restée ouverte.",
                     effects: [FDEffect(attr: .determination, delta: 5), FDEffect(cond: "fatigue", delta: 12), FDEffect(cond: "confiance", delta: 4)]),
            FDChoice(label: "Jouer ton jeu sans surjouer", hint: "Tu as joué ton jeu sans surjouer, exactement comme en club. Sobre, juste, et le sélectionneur a tranché en ta faveur.",
                     effects: [FDEffect(attr: .sangfroid, delta: 3), FDEffect(attr: .placement, delta: 2), FDEffect(cond: "moral", delta: -3)]),
        ]),
    FDSceneDef(
        id: "riv_provocation_publique", category: "Rivalité", minAge: 19, maxAge: 34,
        location: "Plateau télé", character: "Ton rival",
        text: "En direct sur un plateau, ton rival dit posément que tu n'as « jamais rien gagné qui compte ». Le présentateur relance pour être sûr. La séquence tourne partout dans l'heure, et un journaliste t'attend déjà en zone mixte demain avec la citation imprimée.",
        choices: [
            FDChoice(label: "Répondre du tac au tac", hint: "Tu as répondu du tac au tac, et ta réponse a mieux tourné que sa phrase. Le duel est devenu national.",
                     effects: [FDEffect(rel: "media", delta: 6), FDEffect(cond: "reputation", delta: 3), FDEffect(cond: "moral", delta: -2)]),
            FDChoice(label: "Le laisser parler", hint: "Tu l'as laissé parler sans un mot. Il a continué seul, et il a fini par paraître petit.",
                     effects: [FDEffect(attr: .sangfroid, delta: 5), FDEffect(cond: "fatigue", delta: 5)]),
            FDChoice(label: "Le provoquer sur le terrain", hint: "Tu l'as provoqué sur le terrain, au match suivant. Il a pris un carton, et tu as marqué.",
                     effects: [FDEffect(attr: .tacle, delta: 2), FDEffect(cond: "reputation", delta: -3), FDEffect(rel: "fans", delta: 4)]),
        ]),
    FDSceneDef(
        id: "riv_ami_devenu_rival", category: "Rivalité", minAge: 20, maxAge: 34,
        location: "Zone mixte", character: "Un ancien ami",
        text: "Vous êtes arrivés le même été, vous avez partagé les chambres et les galères pendant quatre ans. Depuis que vous jouez la même place, vous ne vous parlez plus qu'aux réunions. Il s'est assis à l'autre bout du bus ce matin, comme depuis six mois.",
        choices: [
            FDChoice(label: "Rétablir le dialogue", hint: "Tu as rétabli le dialogue, en allant t'asseoir à côté de lui. Ça a mis trois trajets, et vous avez retrouvé quelque chose.",
                     effects: [FDEffect(rel: "vestiaire", delta: 6), FDEffect(cond: "moral", delta: 5), FDEffect(cond: "fatigue", delta: 5)]),
            FDChoice(label: "Assumer la guerre froide", hint: "Tu as assumé la guerre froide. Vous êtes tous les deux devenus meilleurs, et vous n'avez plus jamais dîné ensemble.",
                     effects: [FDEffect(attr: .determination, delta: 3), FDEffect(rel: "vestiaire", delta: -3)]),
        ]),
    FDSceneDef(
        id: "riv_geste_antijeu", category: "Rivalité", minAge: 19, maxAge: 34,
        location: "Terrain", character: "Ton rival",
        text: "Sur un corner, hors du champ de l'arbitre, il te marche volontairement sur la cheville de tout son poids. Personne n'a rien vu, ni l'arbitre, ni les caméras. Tu boites deux minutes en serrant les dents. Il te regarde revenir en jouant l'innocent.",
        choices: [
            FDChoice(label: "Le rendre plus tard", hint: "Tu le lui as rendu vingt minutes plus tard, aussi discrètement. Vous êtes quittes, et le compte est ouvert pour dix ans.",
                     effects: [FDEffect(cond: "reputation", delta: -4), FDEffect(cond: "confiance", delta: 3), FDEffect(rel: "vestiaire", delta: 3)]),
            FDChoice(label: "Le signaler à l'arbitre", hint: "Tu l'as signalé à l'arbitre. Il n'avait rien vu, il n'a rien fait, et l'adversaire a souri.",
                     effects: [FDEffect(attr: .sangfroid, delta: 2), FDEffect(rel: "fans", delta: -2)]),
            FDChoice(label: "Ne rien faire et jouer", hint: "Tu n'as rien fait et tu as joué. Tu as marqué à la 80e, ce qui était la seule vraie réponse.",
                     effects: [FDEffect(attr: .sangfroid, delta: 4), FDEffect(attr: .determination, delta: 2), FDEffect(cond: "fatigue", delta: 5)]),
        ]),
    FDSceneDef(
        id: "riv_transfert_meme_club", category: "Rivalité", minAge: 20, maxAge: 34,
        location: "Vestiaire", character: "Ton rival",
        text: "Il signe chez toi. Le club l'annonce ce matin, avec une photo de lui souriant sur ta pelouse, et tout le monde a compris que vous alliez vous partager le même poste. Vous vous détestez poliment depuis six ans. Vous partagez le vestiaire à partir de lundi.",
        choices: [
            FDChoice(label: "Proposer une trêve", hint: "Tu lui as proposé une trêve dès le premier jour. Vous avez fini par très bien jouer ensemble, sans jamais devenir amis.",
                     effects: [FDEffect(rel: "vestiaire", delta: 6), FDEffect(attr: .leadership, delta: 3), FDEffect(cond: "fatigue", delta: 5)]),
            FDChoice(label: "Le prendre comme un défi personnel", hint: "Tu l'as pris comme un défi personnel. Vous avez fait la meilleure saison de vos carrières, et le vestiaire a vécu un enfer.",
                     effects: [FDEffect(attr: .determination, delta: 4), FDEffect(cond: "fatigue", delta: 8)]),
        ]),
    FDSceneDef(
        id: "pre_biographie", category: "Presse", minAge: 26, maxAge: 36,
        location: "Bureau d'édition", character: "Un éditeur",
        text: "Un éditeur te propose ton autobiographie, avec une avance conséquente et une seule exigence : que tu racontes vraiment. Les coulisses, les conflits, les noms. Il a fait vendre trois cent mille exemplaires du dernier joueur qui a accepté, et personne dans le milieu ne lui parle plus.",
        choices: [
            FDChoice(label: "Tout raconter", hint: "Tu as tout raconté, noms compris. Le livre s'est vendu, et quatre personnes du milieu ne te serrent plus la main.",
                     effects: [FDEffect(money: 150000, delta: 0), FDEffect(cond: "reputation", delta: 5), FDEffect(rel: "vestiaire", delta: -8), FDEffect(rel: "president", delta: -6)]),
            FDChoice(label: "Écrire une version sage", hint: "Tu as écrit une version sage. Le livre est joli, personne n'a rien appris, et personne n'a été blessé.",
                     effects: [FDEffect(money: 60000, delta: 0), FDEffect(cond: "reputation", delta: 3), FDEffect(cond: "moral", delta: -3)]),
            FDChoice(label: "Refuser pour l'instant", hint: "Tu as refusé pour l'instant : ce n'est pas fini. L'éditeur t'a dit qu'il rappellerait.",
                     effects: [FDEffect(attr: .sangfroid, delta: 2), FDEffect(rel: "media", delta: -4)]),
        ]),
    FDSceneDef(
        id: "pre_langue_etrangere", category: "Presse", minAge: 19, maxAge: 34,
        location: "Salle de conférence", character: "Un journaliste étranger",
        text: "Première conférence de presse dans ta nouvelle langue, deux mois après ton arrivée. Tu comprends une question sur deux et tu devines le reste. Quinze journalistes attendent, dont trois qui ont déjà écrit que tu ne t'intégrerais jamais. Le traducteur est assis à côté.",
        choices: [
            FDChoice(label: "Répondre dans la langue locale", hint: "Tu as répondu dans leur langue, avec des fautes et un accent. La salle a applaudi à la fin, ce qui ne se fait jamais.",
                     effects: [FDEffect(rel: "media", delta: 8), FDEffect(rel: "fans", delta: 6), FDEffect(cond: "confiance", delta: -2)]),
            FDChoice(label: "Demander un traducteur", hint: "Tu as demandé le traducteur. Les réponses ont été justes, et trois journaux ont titré sur ton refus d'apprendre.",
