        id: "ble_coequipier_grave", category: "Blessure", minAge: 18, maxAge: 36,
        location: "Terrain", character: "Un coéquipier au sol",
        text: "Il est tombé à deux mètres de toi et le bruit a couvert le stade. Le match est arrêté vingt minutes, l'ambulance entre sur la pelouse, et les joueurs des deux équipes se sont mis en cercle en tournant le dos. Tu partages sa chambre en déplacement depuis trois ans.",
        choices: [
            FDChoice(label: "Aller à l'hôpital après le match", hint: "Tu es allé à l'hôpital après le match, encore en tenue. Tu es resté jusqu'à trois heures du matin, et il ne l'oubliera jamais.",
                     effects: [FDEffect(rel: "vestiaire", delta: 8), FDEffect(cond: "moral", delta: -4), FDEffect(cond: "fatigue", delta: 3)]),
            FDChoice(label: "Rester avec le groupe", hint: "Tu es resté avec le groupe, qui en avait besoin aussi. Tu es passé le lendemain matin, avec les autres.",
                     effects: [FDEffect(rel: "vestiaire", delta: 2), FDEffect(cond: "moral", delta: -3)]),
        ]),
    FDSceneDef(
        id: "ble_operation_reportee", category: "Blessure", minAge: 22, maxAge: 36,
        location: "Bureau du coach", character: "Entraîneur principal",
        text: "Le coach te demande de repousser l'opération à la fin de la saison : il reste onze matchs, le club joue tout, et sans toi il n'y a personne à ton poste. Le chirurgien a dit que trois mois de plus n'aggraveraient probablement rien. « Probablement » est le mot important.",
        choices: [
            FDChoice(label: "Accepter", hint: "Tu as accepté de repousser. Tu as fini la saison sur une jambe, le club a atteint son objectif, et l'opération a été plus lourde que prévu.",
                     effects: [FDEffect(rel: "coach", delta: 8), FDEffect(cond: "forme", delta: -8), FDEffect(cond: "fatigue", delta: 10)]),
            FDChoice(label: "Refuser et te faire opérer", hint: "Tu t'es fait opérer tout de suite. Le coach l'a mal pris, et tu étais prêt pour la reprise.",
                     effects: [FDEffect(rel: "coach", delta: -6), FDEffect(cond: "forme", delta: 8)]),
        ]),
    FDSceneDef(
        id: "san_alimentation", category: "Hygiène de vie", minAge: 17, maxAge: 34,
        location: "Réfectoire", character: "Nutritionniste du club",
        text: "Le nutritionniste veut te faire passer trois mois en régime très strict : tout pesé, aucun écart, contrôles hebdomadaires. Il a raison sur les chiffres — ton taux de masse grasse est le plus élevé de l'effectif. Trois mois, c'est aussi Noël, deux anniversaires et un mariage.",
        choices: [
            FDChoice(label: "Suivre à cent pour cent", hint: "Tu as suivi à cent pour cent, y compris à Noël. Trois kilos en moins, des fins de match transformées, et une famille qui a trouvé ça absurde.",
                     effects: [FDEffect(cond: "forme", delta: 8), FDEffect(attr: .endurance, delta: 2), FDEffect(cond: "moral", delta: -3)]),
            FDChoice(label: "Suivre à moitié", hint: "Tu as suivi à moitié. Résultats à moitié, ce qui est logique.",
                     effects: [FDEffect(cond: "forme", delta: 3), FDEffect(cond: "moral", delta: -3)]),
            FDChoice(label: "Refuser", hint: "Tu as refusé le régime. Tu manges comme tu veux, et le préparateur a arrêté de te proposer quoi que ce soit.",
                     effects: [FDEffect(cond: "forme", delta: -4), FDEffect(cond: "moral", delta: 3)]),
        ]),
    FDSceneDef(
        id: "san_sommeil_capteur", category: "Hygiène de vie", minAge: 18, maxAge: 34,
        location: "Chambre", character: "Préparateur physique",
        text: "Le club veut installer un capteur sous ton matelas et suivre tes nuits, chez toi, toute la saison : heures de coucher, réveils, qualité du sommeil, tout remonte au staff le lendemain matin. C'est facultatif, et tous les titulaires ont dit oui.",
        choices: [
            FDChoice(label: "Accepter le suivi", hint: "Tu as accepté le suivi. Les données ont expliqué tes fins de match — et le staff sait à quelle heure tu te couches.",
                     effects: [FDEffect(cond: "fatigue", delta: -12), FDEffect(rel: "coach", delta: 4), FDEffect(cond: "moral", delta: -2)]),
            FDChoice(label: "Refuser au nom de ta vie privée", hint: "Tu as refusé au nom de ta vie privée. C'est ton droit, et tu es le seul du groupe à ne pas apparaître sur leurs courbes.",
                     effects: [FDEffect(rel: "coach", delta: -4), FDEffect(cond: "moral", delta: 3)]),
        ]),
    FDSceneDef(
        id: "san_alcool", category: "Hygiène de vie", minAge: 18, maxAge: 32,
        location: "Soirée d'anniversaire", character: "Un coéquipier",
        text: "Anniversaire d'un coéquipier, restaurant privatisé, milieu de saison. La moitié du groupe boit, l'autre regarde. Il y a séance demain à dix heures, et le préparateur a la liste des présents sans avoir besoin de la demander. On te tend un verre au moment du toast.",
        choices: [
            FDChoice(label: "Boire avec eux", hint: "Tu as bu avec eux, comme tout le monde. La soirée était formidable et la séance du lendemain moins.",
                     effects: [FDEffect(rel: "vestiaire", delta: 6), FDEffect(cond: "forme", delta: -6), FDEffect(cond: "fatigue", delta: 8)]),
            FDChoice(label: "Rester à l'eau", hint: "Tu es resté à l'eau toute la soirée. Deux blagues sur toi, et un test physique impeccable le lendemain.",
                     effects: [FDEffect(cond: "forme", delta: 3), FDEffect(rel: "vestiaire", delta: -2), FDEffect(attr: .determination, delta: 2)]),
            FDChoice(label: "Partir tôt", hint: "Tu es parti tôt, après le gâteau. Compromis correct, personne n'a rien trouvé à redire.",
                     effects: [FDEffect(cond: "fatigue", delta: -4), FDEffect(rel: "vestiaire", delta: 1), FDEffect(cond: "forme", delta: -3)]),
        ]),
    FDSceneDef(
        id: "san_addiction_jeux", category: "Hygiène de vie", minAge: 20, maxAge: 34,
        location: "Appartement", character: "Un ami",
        text: "Un mois que tu joues en ligne jusqu'à trois heures du matin, tous les soirs, et les montants ont changé d'échelle sans que tu saches vraiment quand. Un ami l'a remarqué et t'en parle sur ton canapé, mal à l'aise. Tu as vérifié ton solde deux fois pendant qu'il parlait.",
        choices: [
            FDChoice(label: "Demander de l'aide au club", hint: "Tu as demandé de l'aide au club, ce qui a été le plus dur à faire. Ils ont mis en place un accompagnement, et personne d'autre ne l'a su.",
                     effects: [FDEffect(cond: "moral", delta: 6), FDEffect(rel: "coach", delta: 2), FDEffect(cond: "reputation", delta: -2)]),
            FDChoice(label: "Arrêter seul", hint: "Tu as décidé d'arrêter seul. Tu as tenu trois semaines, puis tu as rouvert l'application un soir de défaite.",
                     effects: [FDEffect(attr: .determination, delta: 4), FDEffect(cond: "fatigue", delta: 6)]),
            FDChoice(label: "Continuer", hint: "Tu as continué. Le solde monte et descend, et tu ne dors toujours pas.",
                     effects: [FDEffect(money: -40000, delta: 0), FDEffect(cond: "fatigue", delta: 12), FDEffect(cond: "forme", delta: -6)]),
        ]),
    FDSceneDef(
        id: "san_tabac", category: "Hygiène de vie", minAge: 18, maxAge: 32,
        location: "Terrasse", character: "Un coéquipier",
        text: "Deux coéquipiers fument derrière le bâtiment après les matchs, depuis des années, et tout le monde fait semblant de ne pas savoir. Ce soir ils t'invitent à les rejoindre, en riant, comme une manière de te faire entrer dans quelque chose. Le préparateur passe parfois par là.",
        choices: [
            FDChoice(label: "Refuser", hint: "Tu as refusé, sans faire la leçon. Ils ont haussé les épaules et ils continuent sans toi.",
                     effects: [FDEffect(cond: "forme", delta: 2), FDEffect(attr: .determination, delta: 2), FDEffect(cond: "moral", delta: -3)]),
            FDChoice(label: "Accepter de temps en temps", hint: "Tu as accepté de temps en temps. Ça reste rare, et ton test d'endurance a baissé sans que tu saches pourquoi.",
                     effects: [FDEffect(rel: "vestiaire", delta: 3), FDEffect(cond: "forme", delta: -4), FDEffect(attr: .endurance, delta: -1)]),
        ]),
    FDSceneDef(
        id: "san_poids", category: "Hygiène de vie", minAge: 22, maxAge: 36,
        location: "Salle de pesée", character: "Préparateur physique",
        text: "Pesée collective à la reprise, chiffres affichés sur l'écran de la salle : quatre kilos de plus qu'à la fin de saison. Le préparateur les annonce à voix haute devant tout le groupe, comme les autres, sans intention particulière. Deux joueurs se sont retournés.",
        choices: [
            FDChoice(label: "Programme intensif immédiat", hint: "Tu as attaqué un programme intensif immédiat. Les quatre kilos sont partis en cinq semaines — et tu as manqué la préparation collective.",
                     effects: [FDEffect(cond: "fatigue", delta: 14), FDEffect(cond: "forme", delta: 6), FDEffect(attr: .endurance, delta: 2)]),
            FDChoice(label: "Perdre doucement", hint: "Tu les as perdus doucement, sur deux mois. Tu es arrivé en forme un peu tard, et sans jamais te casser.",
                     effects: [FDEffect(cond: "forme", delta: 3), FDEffect(rel: "coach", delta: -2)]),
        ]),
    FDSceneDef(
        id: "san_medecine_douce", category: "Hygiène de vie", minAge: 22, maxAge: 36,
        location: "Cabinet", character: "Un thérapeute",
        text: "Un thérapeute recommandé par un ancien joueur promet de régler tes douleurs sans médicament, avec une méthode que le staff médical qualifie poliment de fantaisiste. Deux joueurs jurent que ça a changé leur carrière. Le club te déconseille formellement d'y aller.",
        choices: [
            FDChoice(label: "Essayer", hint: "Tu as essayé. Deux séances, une amélioration que personne ne sait expliquer, et un staff médical furieux.",
                     effects: [FDEffect(cond: "forme", delta: 4), FDEffect(rel: "coach", delta: -3), FDEffect(money: -8000, delta: 0)]),
            FDChoice(label: "S'en tenir au staff médical", hint: "Tu t'en es tenu au staff du club. Le protocole classique a mis plus longtemps, et il a fini par marcher.",
                     effects: [FDEffect(rel: "coach", delta: 4), FDEffect(cond: "forme", delta: 2), FDEffect(cond: "fatigue", delta: 6)]),
        ]),
    FDSceneDef(
        id: "men_pression", category: "Mental", minAge: 18, maxAge: 34,
        location: "Chambre d'hôtel", character: "Préparateur mental",
        text: "Trois heures du matin, chambre d'hôtel, veille de match, et c'est la sixième nuit de suite. Tu connais le plafond par cœur. Le préparateur mental l'a remarqué et propose un suivi régulier, confidentiel, hors du staff. Personne dans ce vestiaire n'a jamais dit oui à ça.",
        choices: [
            FDChoice(label: "Accepter le suivi", hint: "Tu as accepté le suivi. Trois mois plus tard tu dormais, et tu as compris que ça n'avait rien d'une faiblesse.",
                     effects: [FDEffect(attr: .sangfroid, delta: 4), FDEffect(cond: "fatigue", delta: -8), FDEffect(cond: "moral", delta: 4), FDEffect(cond: "confiance", delta: -3)]),
            FDChoice(label: "Refuser, ça passera", hint: "Tu as refusé en disant que ça passerait. Ça n'est pas passé, et tu as appris à jouer avec quatre heures de sommeil.",
                     effects: [FDEffect(cond: "fatigue", delta: 6), FDEffect(cond: "moral", delta: -4)]),
        ]),
    FDSceneDef(
        id: "men_depression", category: "Mental", minAge: 19, maxAge: 36,
        location: "Appartement", character: "Un proche",
        text: "Trois semaines que rien n'a de goût. Pas la défaite, pas la victoire, pas le terrain — surtout pas le terrain. Tu fais les gestes, tu réponds aux messages, tu t'entraînes correctement. Quelqu'un de proche te l'a dit hier soir : « Tu n'es plus là. » Il a raison.",
        choices: [
            FDChoice(label: "En parler au club", hint: "Tu en as parlé au club. Ils ont mis un vrai accompagnement en place, discrètement, et tu es allé mieux.",
                     effects: [FDEffect(cond: "moral", delta: 8), FDEffect(rel: "coach", delta: 3), FDEffect(cond: "reputation", delta: -2)]),
            FDChoice(label: "En parler à tes proches", hint: "Tu en as parlé à tes proches. Ils ne savaient pas quoi faire, et ils ont été là quand même, ce qui a suffi à tenir.",
                     effects: [FDEffect(cond: "moral", delta: 6), FDEffect(rel: "famille", delta: 6), FDEffect(cond: "confiance", delta: -3)]),
            FDChoice(label: "Faire semblant", hint: "Tu as fait semblant. Tu as tenu la saison, et personne n'a rien vu — ce qui est exactement le problème.",
                     effects: [FDEffect(cond: "moral", delta: -8), FDEffect(cond: "forme", delta: -4)]),
        ]),
    FDSceneDef(
        id: "men_peur_echec", category: "Mental", minAge: 18, maxAge: 34,
        location: "Vestiaire", character: "Préparateur mental",
        text: "Un mois que tu ne demandes plus le ballon dans les vingt dernières minutes. Personne ne l'a dit, mais la carte de chaleur ne ment pas : tu disparais quand le match devient serré. Le préparateur mental l'a repérée avant tout le monde et te la montre sans commentaire.",
        choices: [
            FDChoice(label: "Travailler ça en séance", hint: "Tu as travaillé ça en séance, chaque semaine, sans en parler à personne. C'est revenu doucement, et c'est revenu.",
                     effects: [FDEffect(attr: .sangfroid, delta: 4), FDEffect(cond: "confiance", delta: 4), FDEffect(cond: "fatigue", delta: 5)]),
            FDChoice(label: "Forcer le passage en match", hint: "Tu as forcé le passage en match, directement, en réclamant tout. Deux ballons perdus, un but décisif, et le blocage a sauté d'un coup.",
                     effects: [FDEffect(cond: "confiance", delta: 5), FDEffect(cond: "fatigue", delta: 6), FDEffect(attr: .determination, delta: 3)]),
        ]),
    FDSceneDef(
        id: "men_routine_bloquee", category: "Mental", minAge: 18, maxAge: 34,
        location: "Vestiaire", character: "Un coéquipier",
        text: "Bus bloqué une heure, échauffement écourté de moitié, vestiaire trop petit, musique impossible. Ta routine d'avant-match — la même depuis huit ans, à la minute près — est en morceaux, et le coup d'envoi est dans vingt minutes. Ce sont ces détails-là qui te calent.",
        choices: [
            FDChoice(label: "T'adapter sans broncher", hint: "Tu t'es adapté sans broncher, en improvisant une routine en dix minutes. Tu as joué comme d'habitude.",
                     effects: [FDEffect(attr: .sangfroid, delta: 4), FDEffect(cond: "moral", delta: -3)]),
            FDChoice(label: "Perdre tes repères", hint: "Tu as perdu tes repères. Tu es entré sur le terrain à côté de tes crampons, et il t'a fallu une mi-temps.",
                     effects: [FDEffect(cond: "confiance", delta: -5), FDEffect(cond: "moral", delta: -3)]),
        ]),
    FDSceneDef(
        id: "men_confiance_serie", category: "Mental", minAge: 18, maxAge: 36,
        location: "Terrain d'entraînement", character: "Entraîneur principal",
        text: "Dix matchs sans marquer. Le coach te propose de reculer d'un cran, plus loin du but, pour toucher des ballons faciles et te relancer. C'est bienveillant et c'est un aveu : à ton poste, il ne compte plus sur toi pour marquer en ce moment.",
        choices: [
            FDChoice(label: "Accepter le repositionnement", hint: "Tu as accepté le repositionnement. Tu as retrouvé du plaisir et des ballons, et tu n'es jamais remonté devant.",
                     effects: [FDEffect(attr: .passe, delta: 2), FDEffect(attr: .vision, delta: 2), FDEffect(cond: "confiance", delta: 3), FDEffect(cond: "fatigue", delta: 5)]),
            FDChoice(label: "Refuser, tu veux rester devant", hint: "Tu as refusé de reculer. Trois matchs de plus sans marquer, puis un doublé qui a tout débloqué.",
                     effects: [FDEffect(attr: .tir, delta: 2), FDEffect(cond: "confiance", delta: -3), FDEffect(rel: "coach", delta: -3)]),
        ]),
    FDSceneDef(
        id: "men_meditation", category: "Mental", minAge: 19, maxAge: 36,
        location: "Salle calme", character: "Préparateur mental",
        text: "Le club a fait installer une salle calme et impose vingt minutes de méditation deux fois par semaine. La moitié du vestiaire s'en moque ouvertement, deux joueurs dorment carrément, et le préparateur mental fait comme s'il ne voyait rien. Tu es assis au fond.",
        choices: [
            FDChoice(label: "Participer sérieusement", hint: "Tu as joué le jeu sérieusement. Ça a mis six semaines à donner quelque chose, et ça t'a servi tout le reste de ta carrière.",
                     effects: [FDEffect(attr: .sangfroid, delta: 4), FDEffect(rel: "vestiaire", delta: -2), FDEffect(cond: "fatigue", delta: -6)]),
            FDChoice(label: "Faire semblant", hint: "Tu as fait semblant comme les autres. Vingt minutes de sieste deux fois par semaine, ce qui n'est déjà pas si mal.",
                     effects: [FDEffect(rel: "vestiaire", delta: 3), FDEffect(cond: "confiance", delta: -3)]),
        ]),
    FDSceneDef(
        id: "men_objectifs", category: "Mental", minAge: 18, maxAge: 34,
        location: "Bureau du préparateur", character: "Préparateur mental",
        text: "Le préparateur mental demande à chacun d'écrire ses objectifs de saison sur une fiche et de l'afficher dans son casier, visible de tous. Certains ont écrit trois lignes prudentes. Deux ont écrit des chiffres énormes. La tienne est encore vierge sur le banc.",
        choices: [
            FDChoice(label: "Écrire des objectifs très ambitieux", hint: "Tu as écrit des objectifs très ambitieux, affichés en grand. Tout le vestiaire les a lus, et tu as passé la saison à courir après.",
                     effects: [FDEffect(attr: .determination, delta: 4), FDEffect(cond: "confiance", delta: 3), FDEffect(cond: "fatigue", delta: 3)]),
            FDChoice(label: "Écrire des objectifs modestes", hint: "Tu as écrit des objectifs modestes et atteignables. Tu les as tous atteints, et personne n'a rien remarqué.",
                     effects: [FDEffect(attr: .sangfroid, delta: 3), FDEffect(cond: "confiance", delta: 1), FDEffect(cond: "fatigue", delta: 5)]),
        ]),
    FDSceneDef(
        id: "men_burnout", category: "Mental", minAge: 24, maxAge: 36,
        location: "Chambre d'hôtel", character: "Médecin du club",
        text: "Soixante matchs dans la saison, deux compétitions, une sélection. Le corps répond encore — les tests le prouvent — mais tu ne ressens plus rien : ni avant, ni pendant, ni après. Le médecin du club te le dit franchement : ce n'est pas les jambes, c'est la tête, et ça se soigne.",
        choices: [
            FDChoice(label: "Demander deux semaines d'arrêt", hint: "Tu as demandé deux semaines d'arrêt complet. Le club a communiqué sur une gêne musculaire, et tu es revenu vivant.",
                     effects: [FDEffect(cond: "fatigue", delta: -20), FDEffect(cond: "moral", delta: 6), FDEffect(rel: "coach", delta: -5)]),
            FDChoice(label: "Tenir jusqu'à la trêve", hint: "Tu as tenu jusqu'à la trêve. Tu as joué douze matchs de plus en pilote automatique, et la trêve n'a rien réparé.",
                     effects: [FDEffect(cond: "fatigue", delta: 12), FDEffect(attr: .determination, delta: 4)]),
        ]),
    FDSceneDef(
        id: "men_deuil", category: "Mental", minAge: 18, maxAge: 36,
        location: "Cimetière", character: "Ta famille",
        text: "L'enterrement était ce matin. Le match est demain à quinze heures, et le coach t'a laissé décider seul, sans mettre la moindre pression. Tu es encore en costume, assis dans la voiture sur le parking du cimetière, avec le téléphone dans la main depuis un quart d'heure.",
        choices: [
            FDChoice(label: "Jouer pour lui", hint: "Tu as joué pour lui. Tu as marqué et tu as levé les yeux, et tout le stade a compris sans qu'on explique quoi que ce soit.",
                     effects: [FDEffect(attr: .determination, delta: 5), FDEffect(cond: "moral", delta: -4), FDEffect(cond: "confiance", delta: 4)]),
            FDChoice(label: "Demander à ne pas jouer", hint: "Tu as demandé à ne pas jouer. Le club a respecté, le groupe aussi, et tu as passé le dimanche avec ta famille.",
                     effects: [FDEffect(cond: "moral", delta: 4), FDEffect(rel: "coach", delta: -2)]),
        ]),
    FDSceneDef(
        id: "sup_superstition", category: "Superstition", minAge: 17, maxAge: 36,
        location: "Vestiaire", character: "Un coéquipier",
        text: "Les mêmes protège-tibias depuis tes dix ans : rafistolés trois fois, illisibles, indécents. Ils viennent de casser en deux dans ton sac, à trois jours d'un match important. L'intendant t'en propose des neufs, identiques, et tu sais très bien que ce n'est pas la même chose.",
        choices: [
            FDChoice(label: "En chercher des identiques partout", hint: "Tu as passé deux jours à chercher les mêmes partout, jusqu'à en faire venir de l'étranger. Tu as joué avec, et tu as joué tranquille.",
                     effects: [FDEffect(cond: "confiance", delta: 4), FDEffect(cond: "fatigue", delta: 3), FDEffect(money: -500, delta: 0)]),
            FDChoice(label: "Tourner la page", hint: "Tu as tourné la page et pris les neufs. Le premier match a été bizarre, et le deuxième normal.",
                     effects: [FDEffect(attr: .sangfroid, delta: 4), FDEffect(cond: "moral", delta: -2)]),
        ]),
    FDSceneDef(
        id: "sup_rituel_groupe", category: "Superstition", minAge: 18, maxAge: 36,
        location: "Tunnel", character: "Le capitaine",
        text: "Le groupe a adopté un rituel d'avant-match dans le tunnel : une chorégraphie complète, filmée à chaque fois, reprise sur les réseaux du club. Tu trouves ça ridicule et tu l'as dit une fois, en riant. Le capitaine tient au truc, et le tunnel attend.",
        choices: [
            FDChoice(label: "Y participer", hint: "Tu y as participé, à fond, en forçant un peu. Le groupe a apprécié, et la vidéo tourne encore.",
                     effects: [FDEffect(rel: "vestiaire", delta: 5), FDEffect(cond: "moral", delta: 2), FDEffect(cond: "confiance", delta: -3)]),
            FDChoice(label: "T'en tenir à l'écart", hint: "Tu t'en es tenu à l'écart, chaque semaine. Personne ne t'a rien dit — et tu es sur toutes les photos en train de regarder ailleurs.",
                     effects: [FDEffect(rel: "vestiaire", delta: -3), FDEffect(attr: .sangfroid, delta: 2)]),
        ]),
    FDSceneDef(
        id: "sup_numero_porte_bonheur", category: "Superstition", minAge: 18, maxAge: 36,
        location: "Vestiaire", character: "Intendant du club",
        text: "L'intendant t'annonce que le 13 est libre, comme tous les ans : personne n'en veut, y compris les trois recrues arrivées cet été. Il te le propose sans y croire, en te tendant la liste. Les supporters remarqueraient tout de suite, et ils en parleraient toute la saison.",
        choices: [
            FDChoice(label: "Le prendre et en faire ta marque", hint: "Tu l'as pris et tu en as fait ta marque. Deux ans plus tard, le 13 se vend plus que tous les autres à la boutique.",
                     effects: [FDEffect(cond: "confiance", delta: 4), FDEffect(cond: "reputation", delta: 3), FDEffect(rel: "fans", delta: 3), FDEffect(cond: "moral", delta: -2)]),
            FDChoice(label: "Refuser", hint: "Tu as refusé, comme les autres. Le maillot est resté au placard une saison de plus.",
                     effects: [FDEffect(attr: .sangfroid, delta: 1), FDEffect(cond: "confiance", delta: -3)]),
        ]),
    FDSceneDef(
        id: "men_retour_apres_echec", category: "Mental", minAge: 19, maxAge: 36,
        location: "Terrain d'entraînement", character: "Entraîneur principal",
        text: "Tu as raté le penalty décisif dimanche dernier, à la 88e, et ça tourne encore en boucle sur les réseaux. Ce matin, à la fin de la séance, le coach pose un ballon sur le point de penalty et attend. Tout le groupe s'est arrêté de ranger le matériel.",
        choices: [
            FDChoice(label: "Reprendre les tirs immédiatement", hint: "Tu as repris les tirs immédiatement, devant tout le monde. Tu en as mis dix sur dix, et le blocage est mort ce matin-là.",
                     effects: [FDEffect(attr: .sangfroid, delta: 5), FDEffect(attr: .tir, delta: 2), FDEffect(cond: "confiance", delta: 5), FDEffect(cond: "fatigue", delta: 5)]),
            FDChoice(label: "Laisser passer quelques jours", hint: "Tu as demandé quelques jours. Le coach a rangé le ballon sans insister, et tu y as pensé toute la semaine.",
                     effects: [FDEffect(cond: "confiance", delta: -2), FDEffect(cond: "moral", delta: 2)]),
        ]),
    FDSceneDef(
        id: "san_voyage_decalage", category: "Hygiène de vie", minAge: 19, maxAge: 36,
        location: "Avion", character: "Préparateur physique",
        text: "Huit heures de décalage, atterrissage à six heures du matin heure locale, match dans trois jours. Le préparateur distribue un protocole précis : exposition à la lumière, horaires de repas, siestes minutées. Ton corps, lui, réclame de dormir tout de suite pendant douze heures.",
        choices: [
            FDChoice(label: "Suivre le protocole de lumière et de sommeil", hint: "Tu as suivi le protocole à la lettre, lumière et siestes comprises. Tu étais dans le rythme au coup d'envoi.",
