            FDChoice(label: "Dormir quand tu peux", hint: "Tu as dormi quand tu pouvais. Tu as passé le match dans un décalage complet, sans jamais entrer dedans.",
                     effects: [FDEffect(cond: "fatigue", delta: 6), FDEffect(cond: "forme", delta: -3)]),
        ]),
    FDSceneDef(
        id: "san_canicule_entrainement", category: "Hygiène de vie", minAge: 17, maxAge: 34,
        location: "Terrain d'entraînement", character: "Médecin du club",
        text: "Trente-huit degrés à l'ombre, et la séance est maintenue à quinze heures pour des raisons de planning télévisé. Le médecin a fait passer une note au staff, sans effet. Deux joueurs ont déjà vomi à l'échauffement. Le coach regarde qui va oser demander quelque chose.",
        choices: [
            FDChoice(label: "Faire toute la séance", hint: "Tu as fait toute la séance, sans rien demander. Tu as tenu — et tu as mis trois jours à récupérer d'un simple entraînement.",
