            FDChoice(label: "Demander un aménagement", hint: "Tu as demandé un aménagement, pour toi et pour les autres. Le staff a accepté à moitié, et le groupe t'a remercié.",
                     effects: [FDEffect(cond: "fatigue", delta: 6), FDEffect(rel: "coach", delta: -3), FDEffect(attr: .sangfroid, delta: 2)]),
        ]),
    FDSceneDef(
        id: "ble_masque", category: "Blessure", minAge: 19, maxAge: 36,
        location: "Infirmerie", character: "Médecin du club",
        text: "Nez cassé en trois endroits, opéré mardi. Le médecin te propose un masque de protection en carbone qui te permettrait de rejouer dès dimanche — avec une vision périphérique réduite et un risque non nul de tout casser à nouveau au premier duel aérien.",
        choices: [
            FDChoice(label: "Jouer avec le masque", hint: "Tu as joué avec le masque dès dimanche. Tu as vu la moitié du terrain, et tu étais là.",
                     effects: [FDEffect(cond: "confiance", delta: 3), FDEffect(attr: .placement, delta: -1), FDEffect(rel: "coach", delta: 5)]),
            FDChoice(label: "Attendre la consolidation", hint: "Tu as attendu la consolidation complète. Trois semaines de plus, un nez intact, et une place reprise par un autre.",
                     effects: [FDEffect(cond: "forme", delta: 5), FDEffect(rel: "coach", delta: -3)]),
        ]),
    FDSceneDef(
        id: "ble_epaule_gardien", category: "Blessure", minAge: 18, maxAge: 36,
        location: "Infirmerie", character: "Médecin du club",
        text: "L'épaule se déboîte depuis deux mois : trois fois à l'entraînement, une fois en match. Chaque plongeon du mauvais côté peut la faire sortir. Le médecin propose une attelle qui limite l'amplitude, ou l'opération maintenant, avec quatre mois d'arrêt en pleine saison.",
        choices: [
            FDChoice(label: "Jouer avec une attelle", hint: "Tu as joué avec l'attelle. Tu as tenu la saison, en évitant systématiquement un côté — et les attaquants l'ont compris.",
                     effects: [FDEffect(attr: .agilite, delta: -1), FDEffect(cond: "confiance", delta: 3), FDEffect(rel: "coach", delta: 4)]),
            FDChoice(label: "Se faire opérer maintenant", hint: "Tu t'es fait opérer tout de suite. Quatre mois d'arrêt, une épaule solide, et une place à reprendre en revenant.",
                     effects: [FDEffect(cond: "forme", delta: 8), FDEffect(cond: "moral", delta: -4)]),
        ],
        positions: [.gardien]),
    FDSceneDef(
        id: "men_gardien_erreur", category: "Mental", minAge: 18, maxAge: 36,
        location: "Vestiaire", character: "Entraîneur des gardiens",
        text: "Ta sortie ratée a offert le but de la défaite, et la séquence tourne partout depuis vingt-deux heures : montages, ralentis, commentaires. L'entraîneur des gardiens te propose de tout revoir à froid demain matin. Ton téléphone est à côté de toi, écran vers le bas.",
        choices: [
            FDChoice(label: "Analyser froidement la vidéo", hint: "Tu as tout analysé froidement le lendemain, image par image. Tu as compris la faute technique, et elle n'est jamais revenue.",
                     effects: [FDEffect(attr: .sangfroid, delta: 4), FDEffect(attr: .placement, delta: 2), FDEffect(cond: "confiance", delta: 2), FDEffect(cond: "fatigue", delta: 5)]),
            FDChoice(label: "Couper complètement pendant deux jours", hint: "Tu as coupé complètement pendant deux jours : pas de téléphone, pas de vidéo. Tu es revenu la tête claire et sans réponse technique.",
                     effects: [FDEffect(cond: "moral", delta: 5), FDEffect(cond: "fatigue", delta: -6), FDEffect(cond: "confiance", delta: -3)]),
        ],
        positions: [.gardien]),
    FDSceneDef(
        id: "men_defenseur_dribble", category: "Mental", minAge: 18, maxAge: 36,
        location: "Salle vidéo", character: "Analyste vidéo",
        text: "Quatre fois. Le même geste, le même côté, sur le même appui. La vidéo tourne depuis dimanche et l'analyste l'a passée deux fois en réunion sans le faire exprès. Tu affrontes le même joueur dans quinze jours, et tout le monde a la séquence en tête.",
        choices: [
            FDChoice(label: "Travailler le duel toute la semaine", hint: "Tu as travaillé le duel toute la semaine, un contre un, jusqu'à l'écœurement. Au match retour, tu l'as bouclé.",
                     effects: [FDEffect(attr: .tacle, delta: 3), FDEffect(attr: .vitesse, delta: 1), FDEffect(cond: "fatigue", delta: 8)]),
            FDChoice(label: "Travailler le placement pour ne plus subir", hint: "Tu as travaillé le placement pour ne plus jamais te retrouver dans cette situation. Il ne t'a plus éliminé — il est passé ailleurs.",
                     effects: [FDEffect(attr: .placement, delta: 3), FDEffect(attr: .vision, delta: 2), FDEffect(cond: "fatigue", delta: 5)]),
        ],
        positions: [.defenseur]),
    FDSceneDef(
        id: "men_attaquant_disette", category: "Mental", minAge: 18, maxAge: 36,
        location: "Terrain d'entraînement", character: "Entraîneur des attaquants",
        text: "Douze matchs sans marquer. Ce n'est plus une question de jambes : à chaque occasion, tu sens le poids arriver avant le ballon, et tu prends la mauvaise décision une demi-seconde trop tôt. L'entraîneur des attaquants te propose de rester après la séance, ou d'arrêter d'y penser.",
        choices: [
            FDChoice(label: "Rester une heure de plus à la finition", hint: "Tu es resté une heure de plus chaque jour à la finition. Tu as fini par en mettre un — et tu étais épuisé quand c'est arrivé.",
                     effects: [FDEffect(attr: .tir, delta: 3), FDEffect(cond: "fatigue", delta: 10), FDEffect(attr: .determination, delta: 3)]),
            FDChoice(label: "Se libérer et jouer pour les autres", hint: "Tu t'es libéré en jouant pour les autres. Cinq passes décisives en trois matchs, et le but est venu tout seul.",
                     effects: [FDEffect(attr: .vision, delta: 3), FDEffect(rel: "vestiaire", delta: 5), FDEffect(cond: "confiance", delta: 2), FDEffect(cond: "fatigue", delta: 5)]),
        ],
        positions: [.attaquant]),
    FDSceneDef(
        id: "men_milieu_charge", category: "Mental", minAge: 18, maxAge: 36,
        location: "Salle vidéo", character: "Entraîneur adjoint",
        text: "Les données sont formelles : quinze pour cent de distance en moins qu'en début de saison, sur les dix derniers matchs. L'adjoint te montre les courbes sans agressivité. Tu joues mieux techniquement que jamais, et tu cours comme quelqu'un qui a dix ans de plus.",
        choices: [
            FDChoice(label: "Reprendre le travail foncier", hint: "Tu as repris le travail foncier, séances supplémentaires comprises. Tu as retrouvé tes kilomètres, et tu as perdu en fraîcheur technique.",
                     effects: [FDEffect(attr: .endurance, delta: 3), FDEffect(cond: "fatigue", delta: 12)]),
            FDChoice(label: "Économiser et jouer plus juste", hint: "Tu as assumé de courir moins et de jouer plus juste. Ça a marché — jusqu'au jour où l'équipe a eu besoin de tes courses.",
                     effects: [FDEffect(attr: .vision, delta: 3), FDEffect(attr: .passe, delta: 2), FDEffect(cond: "moral", delta: -3)]),
        ],
        positions: [.milieu]),
    FDSceneDef(
        id: "san_ramadan", category: "Hygiène de vie", minAge: 18, maxAge: 36,
        location: "Réfectoire", character: "Nutritionniste du club",
        text: "Tu jeûnes, et le calendrier est chargé : trois matchs en huit jours, dont un déplacement. Le nutritionniste s'inquiète pour tes réserves et propose d'adapter les charges et les horaires de séances. Le club te laisse totalement libre, et deux coéquipiers sont dans le même cas.",
        choices: [
            FDChoice(label: "Adapter les entraînements avec le staff", hint: "Tu as tout adapté avec le staff : horaires décalés, charges revues, repas calés à la minute. Tu as traversé la période sans rien lâcher.",
                     effects: [FDEffect(rel: "coach", delta: 5), FDEffect(cond: "forme", delta: 3), FDEffect(cond: "fatigue", delta: 4)]),
            FDChoice(label: "Ne rien changer", hint: "Tu n'as rien changé à ton entraînement. Tu as tenu par la seule volonté, et le troisième match a été très long.",
                     effects: [FDEffect(cond: "fatigue", delta: 12), FDEffect(attr: .determination, delta: 4), FDEffect(cond: "forme", delta: -4)]),
        ]),
    FDSceneDef(
        id: "men_pere_entraineur", category: "Mental", minAge: 18, maxAge: 30,
        location: "Voiture", character: "Ton père",
        text: "Ton père vient à chaque séance depuis un mois, s'installe au bord du terrain, et a commencé à aborder les adjoints pour parler tactique. Le staff n'a rien dit — encore. Deux coéquipiers en ont fait une blague hier, et tu n'as pas ri du tout.",
        choices: [
            FDChoice(label: "Poser une limite", hint: "Tu as posé une limite claire, un soir, dans la voiture. Ça a été dur, et il n'est plus revenu qu'aux matchs.",
                     effects: [FDEffect(rel: "famille", delta: -4), FDEffect(attr: .sangfroid, delta: 4), FDEffect(rel: "coach", delta: 4)]),
            FDChoice(label: "Le laisser faire", hint: "Tu l'as laissé faire. Il est toujours là, et le staff a commencé à te parler comme à un gamin.",
                     effects: [FDEffect(rel: "famille", delta: 5), FDEffect(rel: "coach", delta: -5)]),
        ]),
    FDSceneDef(
        id: "ble_kine_prive", category: "Blessure", minAge: 22, maxAge: 36,
        location: "Cabinet privé", character: "Un kinésithérapeute",
        text: "Tu veux engager ton propre kinésithérapeute, payé de ta poche, qui te suivrait en plus du staff. Trois joueurs du championnat le font. Le club le prend très mal : ils y voient une défiance publique envers leur cellule médicale, et ils te l'ont fait savoir par écrit.",
        choices: [
            FDChoice(label: "L'engager quand même", hint: "Tu l'as engagé quand même. Ton corps s'en porte mieux, et la cellule médicale du club ne te parle plus qu'en réunion.",
                     effects: [FDEffect(money: -40000, delta: 0), FDEffect(cond: "forme", delta: 8), FDEffect(rel: "coach", delta: -4)]),
            FDChoice(label: "Rester avec le staff du club", hint: "Tu es resté avec le staff du club. La paix est revenue, et tu as suivi le même protocole que tout le monde.",
                     effects: [FDEffect(rel: "coach", delta: 5), FDEffect(cond: "forme", delta: 2), FDEffect(cond: "fatigue", delta: 6)]),
        ]),
    FDSceneDef(
        id: "san_reveil_matinal", category: "Hygiène de vie", minAge: 17, maxAge: 34,
        location: "Chambre", character: "Préparateur physique",
        text: "Séances à sept heures trente, tous les jours pendant six semaines, décision du staff. Tu es quelqu'un du soir depuis toujours : tu t'endors à une heure et tu es incapable de faire autrement. Le préparateur relève les états de forme chaque matin, en début de séance.",
        choices: [
            FDChoice(label: "Te coucher plus tôt et t'y tenir", hint: "Tu as décalé tes soirées pour te coucher à vingt-deux heures. Il a fallu trois semaines pour que ça vienne, et tu es devenu meilleur le matin.",
                     effects: [FDEffect(cond: "fatigue", delta: -8), FDEffect(attr: .determination, delta: 3), FDEffect(cond: "moral", delta: -2)]),
            FDChoice(label: "Arriver dans le dur chaque matin", hint: "Tu es arrivé dans le dur chaque matin, avec cinq heures de sommeil. Le staff l'a vu sur toutes ses courbes.",
                     effects: [FDEffect(cond: "fatigue", delta: 8), FDEffect(rel: "coach", delta: -3)]),
        ]),
    FDSceneDef(
        id: "men_fin_carriere_doute", category: "Mental", minAge: 30, maxAge: 36,
        location: "Vestiaire", character: "Toi-même",
        text: "Trois jours pour récupérer d'un match, contre un seul il y a cinq ans. Tu es assis dans le vestiaire vide, glace sur les deux genoux, et tu viens de te surprendre à compter combien de saisons il reste — pas combien tu en veux, combien il en reste.",
        choices: [
            FDChoice(label: "Planifier une dernière grande saison", hint: "Tu as planifié une dernière grande saison, une seule, en y mettant tout. Tu as fini sur ce que tu voulais laisser.",
                     effects: [FDEffect(attr: .determination, delta: 5), FDEffect(cond: "fatigue", delta: 8), FDEffect(cond: "confiance", delta: 4)]),
            FDChoice(label: "Envisager la retraite sereinement", hint: "Tu as commencé à envisager la retraite sereinement, sans date. Ça t'a enlevé un poids, et un peu de rage aussi.",
                     effects: [FDEffect(cond: "moral", delta: 6), FDEffect(attr: .sangfroid, delta: 3), FDEffect(cond: "fatigue", delta: 5)]),
        ]),
    FDSceneDef(
        id: "men_jeune_pression", category: "Mental", minAge: 17, maxAge: 22,
        location: "Vestiaire", character: "Un cadre du groupe",
        text: "« Le futur crack », c'est écrit partout depuis six mois : dans les journaux, sur les réseaux, dans la bouche du président. Tu as vingt ans et onze matchs professionnels. Un cadre du vestiaire te l'a dit hier, gentiment : « Ils vont te détruire si tu les écoutes. »",
        choices: [
            FDChoice(label: "Assumer l'étiquette", hint: "Tu as assumé l'étiquette et tu l'as portée haut. Ça t'a donné une confiance énorme, et chaque match moyen est devenu un procès.",
                     effects: [FDEffect(cond: "confiance", delta: 5), FDEffect(cond: "fatigue", delta: 4), FDEffect(rel: "media", delta: 4)]),
            FDChoice(label: "Demander qu'on te laisse tranquille", hint: "Tu as demandé qu'on te laisse tranquille, publiquement. La pression est retombée, et une partie des gens t'a trouvé prétentieux.",
                     effects: [FDEffect(attr: .sangfroid, delta: 3), FDEffect(rel: "media", delta: -3), FDEffect(cond: "moral", delta: 3)]),
        ]),
    FDSceneDef(
        id: "ble_saison_blanche", category: "Blessure", minAge: 19, maxAge: 36,
        location: "Salle de rééducation", character: "Kinésithérapeute",
        text: "Une saison entière en rééducation. Le groupe a changé : deux recrues à ton poste, un nouveau coach, des habitudes que tu ne connais pas. Tu passes tes journées dans une salle à côté du vestiaire, à entendre les autres rire à travers la cloison, et personne ne fait exprès.",
        choices: [
            FDChoice(label: "Venir chaque jour au centre malgré tout", hint: "Tu es venu chaque jour au centre, aux repas, aux réunions, même sans jouer. Le groupe ne t'a jamais perdu.",
                     effects: [FDEffect(rel: "vestiaire", delta: 6), FDEffect(cond: "moral", delta: 4), FDEffect(cond: "fatigue", delta: 4)]),
            FDChoice(label: "Te soigner loin du club", hint: "Tu es allé te soigner loin du club, au calme. Tu es revenu guéri, dans un vestiaire où plus personne ne te connaissait.",
                     effects: [FDEffect(cond: "forme", delta: 6), FDEffect(rel: "vestiaire", delta: -5)]),
        ]),
    FDSceneDef(
        id: "san_don_sang", category: "Hygiène de vie", minAge: 20, maxAge: 36,
        location: "Centre de don", character: "Une infirmière",
        text: "Le club accueille une campagne de don du sang et l'association espère l'image d'un joueur. Le staff médical déconseille formellement en pleine saison : quarante-huit heures de baisse de performance, minimum. Il y a une file de gens dans le hall, et une caméra.",
        choices: [
            FDChoice(label: "Donner quand même", hint: "Tu as donné quand même. Deux jours de jambes lourdes, et une file d'attente qui a doublé le lendemain.",
                     effects: [FDEffect(cond: "reputation", delta: 5), FDEffect(cond: "forme", delta: -3), FDEffect(rel: "fans", delta: 4)]),
            FDChoice(label: "Attendre la trêve", hint: "Tu as attendu la trêve pour donner, sans caméra. Personne ne l'a su, et le sang était le même.",
                     effects: [FDEffect(attr: .sangfroid, delta: 2), FDEffect(cond: "forme", delta: -3)]),
        ]),
    FDSceneDef(
        id: "men_psy_public", category: "Mental", minAge: 21, maxAge: 36,
        location: "Plateau télé", character: "Un journaliste",
        text: "Plateau télé, question directe, en direct : est-ce que tu consultes un psychologue ? La salle attend. C'est encore un sujet tabou dans ce vestiaire et dans ce pays, et ta réponse sera reprise partout — quelle qu'elle soit, et surtout si elle est honnête.",
        choices: [
            FDChoice(label: "Répondre honnêtement", hint: "Tu as répondu honnêtement, oui, et pourquoi. Le sujet a occupé la presse une semaine, et trois joueurs t'ont écrit en privé pour te remercier.",
                     effects: [FDEffect(cond: "reputation", delta: 8), FDEffect(rel: "media", delta: 6), FDEffect(rel: "vestiaire", delta: -2)]),
            FDChoice(label: "Éluder", hint: "Tu as éludé. Personne n'a insisté, et rien n'a bougé sur ce sujet-là.",
                     effects: [FDEffect(attr: .sangfroid, delta: 2), FDEffect(cond: "moral", delta: -3)]),
        ]),
    FDSceneDef(
        id: "sup_maillot_fetiche", category: "Superstition", minAge: 18, maxAge: 36,
        location: "Vestiaire", character: "Intendant du club",
        text: "Le même sous-maillot depuis trois ans, sous chaque maillot, à chaque match. Il est troué à deux endroits, délavé, et l'intendant a décidé qu'il le jetait cette semaine — il l'a même sorti du panier et posé sur le banc pour que tu le voies bien.",
        choices: [
            FDChoice(label: "Le garder", hint: "Tu l'as récupéré et gardé. Il est encore plus troué, et il est encore là.",
                     effects: [FDEffect(cond: "confiance", delta: 3), FDEffect(rel: "staff", delta: -2)]),
            FDChoice(label: "Le laisser partir", hint: "Tu l'as laissé partir. Tu as joué sans, et il ne s'est rien passé du tout.",
                     effects: [FDEffect(attr: .sangfroid, delta: 3), FDEffect(cond: "confiance", delta: -3)]),
        ]),
    FDSceneDef(
        id: "men_rechute_confiance", category: "Mental", minAge: 19, maxAge: 36,
        location: "Bord du terrain", character: "Entraîneur adjoint",
        text: "L'adjoint t'arrête au bord du terrain, sans témoin : « Tu joues la peur au ventre depuis un mois. Tu ne prends plus un risque. » Il n'a pas dit ça pour te blesser, et c'est bien pour ça que ça touche. Tu sais exactement de quel match ça date.",
        choices: [
            FDChoice(label: "Reconnaître et travailler", hint: "Tu as reconnu, et vous avez travaillé ça ensemble pendant six semaines. C'est revenu, plus solide qu'avant.",
                     effects: [FDEffect(attr: .sangfroid, delta: 4), FDEffect(cond: "confiance", delta: 4), FDEffect(rel: "coach", delta: 4), FDEffect(cond: "fatigue", delta: 5)]),
            FDChoice(label: "Nier en bloc", hint: "Tu as nié en bloc. Il n'en a plus jamais reparlé, et tu as continué comme ça jusqu'en février.",
                     effects: [FDEffect(cond: "confiance", delta: -3), FDEffect(rel: "coach", delta: -3)]),
        ]),
    FDSceneDef(
        id: "ble_prevention", category: "Blessure", minAge: 22, maxAge: 36,
        location: "Salle de soins", character: "Préparateur physique",
        text: "Quarante minutes de protocole préventif avant chaque séance : renforcement, mobilité, activation, tous les jours, toute l'année. C'est ennuyeux, ça ne se voit jamais, et le préparateur affirme que ça diminue de moitié le risque de blessure musculaire.",
        choices: [
            FDChoice(label: "Le suivre tous les jours", hint: "Tu l'as fait tous les jours, sans exception, pendant toute la saison. Zéro blessure musculaire — et quarante minutes de ta vie chaque matin.",
                     effects: [FDEffect(cond: "forme", delta: 8), FDEffect(cond: "fatigue", delta: 4)]),
            FDChoice(label: "Le sauter quand tu es pressé", hint: "Tu l'as sauté dès que tu étais pressé. Tu as gagné du temps, et tu as manqué cinq semaines en mars.",
                     effects: [FDEffect(cond: "forme", delta: -5), FDEffect(cond: "fatigue", delta: -2)]),
        ]),
    FDSceneDef(
        id: "san_famille_cuisine", category: "Hygiène de vie", minAge: 19, maxAge: 34,
        location: "Cuisine", character: "Ta mère",
        text: "Ta mère a lu le régime du club, l'a trouvé absurde, et continue de cuisiner comme elle l'a toujours fait. Le dimanche, la table est pleine, et refuser son plat n'est pas juste une question de calories dans cette maison. Le contrôle du poids est le lundi matin.",
        choices: [
            FDChoice(label: "Manger chez toi la semaine", hint: "Tu manges selon le protocole la semaine, chez toi. Le dimanche est devenu un jour un peu tendu.",
                     effects: [FDEffect(cond: "forme", delta: 5), FDEffect(rel: "famille", delta: -4)]),
            FDChoice(label: "Faire une exception le dimanche", hint: "Tu fais une exception chaque dimanche, sans culpabiliser. Le lundi n'est jamais bon, et la maison est restée la maison.",
                     effects: [FDEffect(cond: "moral", delta: 5), FDEffect(rel: "famille", delta: 6), FDEffect(cond: "forme", delta: -2)]),
        ]),
    FDSceneDef(
