        text: "Le spécialiste est formel, sans dramatiser : une saison de plus à ce niveau et ton genou ne sera plus jamais le même — pas seulement pour le football, pour tout le reste. Tu as trente et un ans, un contrat en cours, et une équipe qui compte sur toi en janvier.",
        choices: [
            FDChoice(label: "Arrêter maintenant", hint: "Tu as arrêté tout de suite. Tu marches normalement, tu joues avec tes enfants, et tu as raccroché avant l'heure.",
                     effects: [FDEffect(cond: "moral", delta: -6), FDEffect(cond: "reputation", delta: 4)]),
            FDChoice(label: "Jouer une dernière saison", hint: "Tu as joué une dernière saison. Elle a été belle — et tu boites les matins d'hiver depuis.",
                     effects: [FDEffect(cond: "forme", delta: -10), FDEffect(attr: .determination, delta: 5), FDEffect(cond: "confiance", delta: 4)]),
        ]),
    FDSceneDef(
        id: "vet_role_mentor", category: "Vétéran", minAge: 30, maxAge: 36,
        location: "Centre de formation", character: "Directeur du centre",
        text: "Le club te demande d'encadrer les jeunes deux matinées par semaine, en plus de ton contrat, sans rémunération supplémentaire. Ce sont deux matinées prises sur ta récupération, à trente-deux ans, quand ton corps réclame exactement le contraire.",
        choices: [
            FDChoice(label: "Accepter", hint: "Tu as accepté. Les gamins ont appris des choses qu'aucun éducateur ne pouvait leur apprendre, et tu as récupéré moins bien.",
