            FDChoice(label: "Refuser", hint: "Tu as refusé pour préserver ton corps. Le club a compris, et il a noté que tu n'étais pas disponible.",
                     effects: [FDEffect(cond: "fatigue", delta: -2), FDEffect(rel: "president", delta: -3)]),
        ]),
    FDSceneDef(
        id: "sta_influence_transferts", category: "Star", minAge: 25, maxAge: 36,
        location: "Bureau du directeur sportif", character: "Directeur sportif",
        text: "Le directeur sportif te consulte sur les recrues, ce qui ne se fait jamais. Sur la liste des cinq noms, il y a un ami à toi — bon joueur, pas le meilleur des cinq, et le seul dont tu connais la famille. Ton avis pèsera lourd, et il le sait.",
        choices: [
            FDChoice(label: "Le recommander", hint: "Tu l'as recommandé. Il a signé, il a fait une saison correcte, et deux personnes du club savent pourquoi il est là.",
                     effects: [FDEffect(rel: "vestiaire", delta: 5), FDEffect(rel: "president", delta: -2), FDEffect(money: 35000, delta: 0)]),
            FDChoice(label: "Rester objectif", hint: "Tu es resté objectif et tu as désigné le meilleur des cinq. Ton ami l'a appris, et vous n'en avez jamais reparlé.",
                     effects: [FDEffect(attr: .leadership, delta: 4), FDEffect(rel: "president", delta: 6), FDEffect(rel: "vestiaire", delta: -3)]),
        ]),
    FDSceneDef(
        id: "trophee_coupe_monde", category: "Trophée", minAge: 22, maxAge: 36,
        location: "Vestiaire de la sélection", character: "Sélectionneur",
        text: "Finale de Coupe du monde dans trois jours. Tu es revenu de blessure il y a dix jours, tu as joué vingt minutes en demi-finale, et le sélectionneur hésite ouvertement à te titulariser. Il te reçoit et te demande, les yeux dans les yeux, où tu en es vraiment.",
        choices: [
            FDChoice(label: "Le convaincre que tu es prêt", hint: "Tu l'as convaincu que tu étais prêt. Tu as commencé la finale, et ton corps a tenu soixante minutes.",
                     effects: [FDEffect(cond: "confiance", delta: 5), FDEffect(cond: "forme", delta: -6), FDEffect(attr: .determination, delta: 5)]),
            FDChoice(label: "Reconnaître que tu n'es pas à cent pour cent", hint: "Tu as reconnu que tu n'étais pas à cent pour cent. Il t'a fait entrer à l'heure de jeu, frais, et tu as pesé.",
                     effects: [FDEffect(attr: .sangfroid, delta: 4), FDEffect(rel: "coach", delta: 5), FDEffect(cond: "fatigue", delta: 5)]),
        ]),
    FDSceneDef(
        id: "trophee_defaite_finale", category: "Trophée", minAge: 21, maxAge: 36,
        location: "Pelouse", character: "Le stade",
        text: "Finale perdue aux tirs au but. Le tien est passé au-dessus. Le stade adverse célèbre à trente mètres, tes coéquipiers sont au sol, et le parcage de tes supporters est resté debout, immobile, à regarder vers vous. Personne ne bouge depuis deux minutes.",
        choices: [
            FDChoice(label: "Aller devant les supporters t'excuser", hint: "Tu es allé devant tes supporters t'excuser, seul, sous les applaudissements. Ils ont chanté ton nom pendant cinq minutes.",
                     effects: [FDEffect(rel: "fans", delta: 8), FDEffect(cond: "reputation", delta: 5), FDEffect(cond: "moral", delta: -5)]),
            FDChoice(label: "Rentrer directement au vestiaire", hint: "Tu es rentré directement au vestiaire, sans lever la tête. Personne ne t'en a voulu, et tu t'en veux encore.",
                     effects: [FDEffect(cond: "moral", delta: -8)]),
        ]),
    FDSceneDef(
        id: "sta_double_vie", category: "Star", minAge: 22, maxAge: 34,
        location: "Appartement", character: "Ta compagne",
        text: "Elle ne demande pas grand-chose : deux soirées par semaine sans téléphone, un dimanche sur deux sans obligation, un dîner sans que quelqu'un vienne à la table. Elle a fait la liste, calmement, et elle te la lit dans la cuisine. Ton planning est plein jusqu'en juin.",
        choices: [
            FDChoice(label: "Réduire les engagements", hint: "Tu as réduit tes engagements de moitié. Tu as perdu deux partenaires, et tu as retrouvé ta maison.",
                     effects: [FDEffect(money: -40000, delta: 0), FDEffect(cond: "moral", delta: 8), FDEffect(rel: "famille", delta: 8)]),
            FDChoice(label: "Continuer sur ce rythme", hint: "Tu as continué sur ce rythme. Le compte en banque est superbe, et la liste est restée sur le frigo.",
                     effects: [FDEffect(money: 40000, delta: 0), FDEffect(cond: "fatigue", delta: 10), FDEffect(rel: "famille", delta: -6)]),
        ]),
    FDSceneDef(
        id: "vet_dernier_contrat_etranger", category: "Vétéran", minAge: 31, maxAge: 36,
        location: "Salon d'hôtel", character: "Un émissaire étranger",
        text: "Un dernier gros contrat, très loin, dans un championnat sans public ni exigence : deux ans, une somme qui met ta famille à l'abri pour de bon. Tu ne joueras plus jamais devant les tiens, et personne en France ne verra un seul de tes matchs.",
        choices: [
            FDChoice(label: "Partir", hint: "Tu es parti. Deux ans loin de tout, un compte en banque définitivement réglé, et une fin de carrière que personne n'a vue.",
                     effects: [FDEffect(money: 300000, delta: 0), FDEffect(rel: "famille", delta: -6), FDEffect(cond: "reputation", delta: -3)]),
            FDChoice(label: "Finir chez toi", hint: "Tu as choisi de finir chez toi, pour beaucoup moins. Ta famille a vu tes derniers matchs depuis la tribune.",
                     effects: [FDEffect(cond: "moral", delta: 8), FDEffect(rel: "fans", delta: 8), FDEffect(cond: "forme", delta: -3)]),
        ]),
    FDSceneDef(
        id: "fin_livre_transmission", category: "Retraite", minAge: 32, maxAge: 36,
        location: "Bureau", character: "Un éditeur",
        text: "Un éditeur veut un livre technique sur ta manière de jouer : ton geste, tes appuis, ta lecture du jeu, expliqués pour des jeunes joueurs. Ça demande des mois de travail avec un rédacteur, et ça revient à donner ce que tu as passé vingt ans à construire.",
        choices: [
            FDChoice(label: "L'écrire sérieusement", hint: "Tu l'as écrit sérieusement, pendant deux ans. Des milliers de gamins travaillent avec, et tu as tout donné.",
                     effects: [FDEffect(cond: "reputation", delta: 6), FDEffect(attr: .vision, delta: 3), FDEffect(cond: "fatigue", delta: 6)]),
            FDChoice(label: "Refuser", hint: "Tu as refusé. Ce que tu sais reste à toi, et personne ne l'apprendra de cette façon-là.",
                     effects: [FDEffect(attr: .sangfroid, delta: 1), FDEffect(cond: "moral", delta: -3)]),
        ]),
    FDSceneDef(
        id: "sta_agent_sportif_futur", category: "Star", minAge: 28, maxAge: 36,
        location: "Bureau de l'agent", character: "Ton agent",
        text: "Ton agent te propose de devenir associé de son agence après ta carrière : ton carnet d'adresses, ton nom, ta connaissance du vestiaire contre une part de la société. C'est une reconversion toute tracée, et c'est passer de l'autre côté de la table pour toujours.",
        choices: [
            FDChoice(label: "Accepter", hint: "Tu as accepté. Ta reconversion est réglée, et tu négocies désormais contre des joueurs comme toi.",
                     effects: [FDEffect(money: -50000, delta: 0), FDEffect(rel: "agent", delta: 10), FDEffect(attr: .vision, delta: 3)]),
            FDChoice(label: "Refuser", hint: "Tu as refusé. Tu ne te voyais pas de ce côté-là de la table, et il ne t'a jamais tout à fait pardonné.",
                     effects: [FDEffect(attr: .sangfroid, delta: 2), FDEffect(rel: "agent", delta: -3)]),
        ]),
    FDSceneDef(
        id: "vet_place_banc", category: "Vétéran", minAge: 31, maxAge: 36,
        location: "Banc de touche", character: "Entraîneur principal",
        text: "Troisième match consécutif sur le banc, à trente-quatre ans. Tu t'échauffes toutes les vingt minutes pour rien, tu applaudis, tu rentres. Le mercato d'hiver ouvre dans trois semaines et deux clubs ont appelé ton agent. Le groupe te regarde beaucoup en ce moment.",
        choices: [
            FDChoice(label: "Rester exemplaire et soutenir le groupe", hint: "Tu es resté exemplaire : premier à l'échauffement, premier à féliciter. Le vestiaire n'a rien perdu, et toi non plus rien gagné.",
                     effects: [FDEffect(rel: "vestiaire", delta: 8), FDEffect(attr: .leadership, delta: 4), FDEffect(cond: "moral", delta: -2)]),
            FDChoice(label: "Demander à partir en janvier", hint: "Tu as demandé à partir en janvier. Le club a accepté, et tu as rejoué tous les week-ends ailleurs.",
                     effects: [FDEffect(rel: "coach", delta: -4), FDEffect(cond: "confiance", delta: 3)]),
        ]),
    FDSceneDef(
        id: "trophee_record_selection", category: "Trophée", minAge: 29, maxAge: 36,
        location: "Centre national", character: "Sélectionneur",
        text: "Trois sélections du record national, un record vieux de vingt-neuf ans. Le sélectionneur, lui, veut rajeunir avant le prochain tournoi et te l'a dit sans détour. Trois matchs, trois convocations, et le record est à toi. Trois places qui n'iront pas à des jeunes.",
        choices: [
            FDChoice(label: "Demander à jouer ces trois matchs", hint: "Tu as demandé à jouer ces trois matchs. Le record est tombé, et le sélectionneur ne t'a plus rappelé.",
                     effects: [FDEffect(cond: "reputation", delta: 5), FDEffect(rel: "coach", delta: -3), FDEffect(cond: "confiance", delta: 3)]),
            FDChoice(label: "Laisser la place aux jeunes", hint: "Tu as laissé la place aux jeunes. Le record est resté à un autre, et le sélectionneur l'a raconté partout.",
                     effects: [FDEffect(cond: "reputation", delta: 8), FDEffect(attr: .leadership, delta: 4), FDEffect(rel: "vestiaire", delta: -3)]),
        ]),
    FDSceneDef(
        id: "sta_investissement_club", category: "Star", minAge: 29, maxAge: 36,
        location: "Salle de réunion", character: "Un investisseur",
        text: "On te propose d'entrer au capital d'un club de troisième division, avec ton nom en vitrine et un rôle de vice-président. L'investissement est important, le projet est sérieux sur le papier, et ton nom serait attaché à tout ce qui arrivera à ce club pendant dix ans.",
        choices: [
            FDChoice(label: "Investir", hint: "Tu as investi. Le club a monté d'une division, et ton nom est associé à chaque décision impopulaire.",
                     effects: [FDEffect(money: -150000, delta: 0), FDEffect(attr: .vision, delta: 3), FDEffect(cond: "reputation", delta: 4)]),
            FDChoice(label: "Refuser", hint: "Tu as refusé. Le club est monté deux fois sans toi, et tu as gardé ton argent et ton nom.",
                     effects: [FDEffect(attr: .sangfroid, delta: 2), FDEffect(money: -10000, delta: 0)]),
        ]),
    FDSceneDef(
        id: "fin_retour_terrain", category: "Retraite", minAge: 33, maxAge: 36,
        location: "Terrain municipal", character: "Un dirigeant amateur",
        text: "Un club amateur de ton quartier te propose de jouer le dimanche, en district, pour le plaisir. Pas de préparation, pas de pression, des vestiaires sans eau chaude. Ta carrière est finie depuis un an, et ton corps s'en est remis. Ils jouent à quatre cents mètres de chez toi.",
        choices: [
            FDChoice(label: "Accepter", hint: "Tu as accepté. Tu joues le dimanche en district, et tu n'as jamais autant aimé le football.",
                     effects: [FDEffect(cond: "moral", delta: 10), FDEffect(rel: "fans", delta: 6), FDEffect(cond: "reputation", delta: -2)]),
            FDChoice(label: "Refuser, la page est tournée", hint: "Tu as refusé : la page est tournée pour de bon. Tu passes devant le terrain le dimanche matin, et tu continues à rouler.",
                     effects: [FDEffect(attr: .sangfroid, delta: 3), FDEffect(cond: "moral", delta: 3), FDEffect(cond: "fatigue", delta: 5)]),
        ]),
    FDSceneDef(
        id: "sta_pression_stats", category: "Star", minAge: 22, maxAge: 34,
        location: "Salle vidéo", character: "Analyste vidéo",
        text: "Les données avancées disent que tu baisses depuis six mois : moins de sprints, moins de duels gagnés, moins de courses sans ballon. Tes buts, eux, sont au même niveau. L'analyste te montre les deux courbes côte à côte, et ne dit pas laquelle il faut croire.",
        choices: [
            FDChoice(label: "Travailler ce que disent les données", hint: "Tu as travaillé exactement ce que disaient les données. Les courbes sont remontées, et ton jeu a changé.",
