            FDChoice(label: "Te fier à tes sensations", hint: "Tu t'es fié à tes sensations et à tes buts. Tu as continué à marquer, et le club a commencé à chercher plus jeune.",
                     effects: [FDEffect(cond: "confiance", delta: 4), FDEffect(attr: .tir, delta: 1), FDEffect(cond: "fatigue", delta: 6)]),
        ]),
    FDSceneDef(
        id: "vet_conflit_jeune_star", category: "Vétéran", minAge: 30, maxAge: 36,
        location: "Vestiaire", character: "Une jeune star du groupe",
        text: "Il a vingt ans, il est déjà meilleur que la moitié du vestiaire, et il ne respecte plus rien : retards, remarques en réunion, chambrage des anciens. Ce matin, il t'a testé ouvertement devant tout le monde. Le staff n'a pas bougé et attend visiblement que quelqu'un le fasse.",
        choices: [
            FDChoice(label: "Le recadrer devant le groupe", hint: "Tu l'as recadré devant tout le groupe, sèchement. Il a filé droit pendant trois mois — et il ne t'a plus adressé la parole.",
                     effects: [FDEffect(attr: .leadership, delta: 4), FDEffect(rel: "vestiaire", delta: 4), FDEffect(cond: "moral", delta: -2)]),
            FDChoice(label: "Le prendre à part", hint: "Tu l'as pris à part, longuement, sans témoin. Il a changé pour de bon, et il te doit quelque chose.",
                     effects: [FDEffect(attr: .leadership, delta: 5), FDEffect(rel: "vestiaire", delta: 6), FDEffect(cond: "fatigue", delta: 7)]),
            FDChoice(label: "Laisser le staff gérer", hint: "Tu as laissé le staff gérer. Le staff n'a rien fait, et ça a pourri l'ambiance jusqu'en mai.",
                     effects: [FDEffect(rel: "coach", delta: 2), FDEffect(rel: "vestiaire", delta: -3)]),
        ]),
    FDSceneDef(
        id: "trophee_prix_fair_play", category: "Trophée", minAge: 20, maxAge: 36,
        location: "Cérémonie", character: "Un dirigeant de la ligue",
        text: "Tu reçois le prix du fair-play de la saison : zéro carton rouge, deux jaunes, et un geste remarqué en novembre. Une partie du vestiaire en rigole depuis l'annonce — le trophée des gentils, celui qu'on gagne quand on n'a rien gagné d'autre. La cérémonie est ce soir.",
        choices: [
            FDChoice(label: "Le revendiquer", hint: "Tu l'as revendiqué, sur scène, en expliquant pourquoi ça comptait. Une partie du milieu t'a soutenu, l'autre a souri.",
                     effects: [FDEffect(cond: "reputation", delta: 6), FDEffect(rel: "vestiaire", delta: -2)]),
            FDChoice(label: "En rire avec eux", hint: "Tu en as ri avec eux, le premier. Le trophée est dans un carton, et le vestiaire t'a trouvé sympa.",
                     effects: [FDEffect(rel: "vestiaire", delta: 5), FDEffect(cond: "reputation", delta: 2), FDEffect(cond: "fatigue", delta: 5)]),
        ]),
    FDSceneDef(
        id: "sta_conflit_marque", category: "Star", minAge: 22, maxAge: 34,
        location: "Bureau de l'agent", character: "Directeur marketing",
        text: "Ton équipementier sort un nouveau modèle et exige que tu le portes en match : couleur criarde, coupe différente, et tu as testé une paire à l'entraînement sans réussir à t'y faire. Le contrat est clair. Le service marketing a déjà prévu ta photo pour la campagne.",
        choices: [
            FDChoice(label: "Porter le modèle", hint: "Tu as porté le modèle, comme prévu. Tu as joué trois mois avec des chaussures que tu détestes.",
                     effects: [FDEffect(money: 60000, delta: 0), FDEffect(cond: "confiance", delta: -3)]),
            FDChoice(label: "Négocier une version personnalisée", hint: "Tu as négocié une version personnalisée, à ta pointure et à tes couleurs. Ça a pris six semaines, et ils ont cédé.",
                     effects: [FDEffect(money: 20000, delta: 0), FDEffect(rel: "agent", delta: 4), FDEffect(cond: "confiance", delta: 2), FDEffect(cond: "fatigue", delta: 6)]),
        ]),
    FDSceneDef(
        id: "fin_hommage_club", category: "Retraite", minAge: 32, maxAge: 36,
        location: "Pelouse", character: "Président du club",
        text: "Le club retire ton numéro : plus personne ne le portera. Cérémonie avant le match, maillot encadré, ta famille sur la pelouse, quarante mille personnes debout. Le président te tend le micro à la fin, ce qui n'était pas prévu dans le déroulé qu'on t'a fait lire.",
        choices: [
            FDChoice(label: "Prendre le micro", hint: "Tu as pris le micro. Tu as parlé du club, des gens, de ce que ça t'a coûté — et le stade a écouté en silence.",
                     effects: [FDEffect(cond: "reputation", delta: 8), FDEffect(rel: "fans", delta: 10), FDEffect(cond: "moral", delta: 8), FDEffect(cond: "fatigue", delta: 5)]),
            FDChoice(label: "Saluer sans parler", hint: "Tu as salué sans parler, la main sur le cœur, en faisant le tour des quatre tribunes. Certains disent que c'était mieux ainsi.",
                     effects: [FDEffect(attr: .sangfroid, delta: 4), FDEffect(cond: "moral", delta: 5), FDEffect(cond: "fatigue", delta: 5)]),
        ]),
    FDSceneDef(
        id: "vet_salaire_jeune", category: "Vétéran", minAge: 30, maxAge: 36,
        location: "Vestiaire", character: "Un jeune du groupe",
        text: "Un joueur de vingt ans arrivé en août gagne le double de toi, et il l'a dit à voix haute dans le vestiaire, en riant, en montrant sa montre. Tu es là depuis neuf ans, tu as porté le brassard trois saisons. Le vestiaire s'est tu et personne ne regarde dans ta direction.",
        choices: [
            FDChoice(label: "Ne rien dire", hint: "Tu n'as rien dit. Le marché est le marché, et tu as digéré ça tout seul pendant des mois.",
                     effects: [FDEffect(attr: .sangfroid, delta: 4), FDEffect(cond: "forme", delta: -3)]),
            FDChoice(label: "Aller voir la direction", hint: "Tu es allé voir la direction pour renégocier. Ils ont refusé poliment, et l'ambiance a changé.",
                     effects: [FDEffect(rel: "president", delta: -4), FDEffect(money: 30000, delta: 0)]),
            FDChoice(label: "Le recadrer", hint: "Tu l'as recadré, sur le fond et sur la forme. Il a rangé sa montre, et il ne t'a plus jamais parlé d'argent.",
                     effects: [FDEffect(attr: .leadership, delta: 3), FDEffect(rel: "vestiaire", delta: 2), FDEffect(cond: "forme", delta: -3)]),
        ]),
    FDSceneDef(
        id: "sta_visite_officielle", category: "Star", minAge: 23, maxAge: 36,
        location: "Palais officiel", character: "Un dignitaire",
        text: "L'équipe est reçue officiellement après le titre : palais, protocole, discours, télévision nationale. On demande un joueur pour représenter le groupe et le capitaine te désigne devant tout le monde. Tu as trois minutes pour préparer quelque chose.",
        choices: [
            FDChoice(label: "Faire le discours", hint: "Tu as fait le discours. Il était court, juste, et tu es passé de joueur à figure du club ce jour-là.",
                     effects: [FDEffect(attr: .leadership, delta: 4), FDEffect(cond: "reputation", delta: 6), FDEffect(rel: "media", delta: 5), FDEffect(money: -10000, delta: 0)]),
            FDChoice(label: "Laisser le capitaine parler", hint: "Tu as laissé le capitaine parler, comme le protocole le prévoyait. C'était plus simple, et personne n'a rien remarqué.",
                     effects: [FDEffect(rel: "capitaine", delta: 5), FDEffect(attr: .sangfroid, delta: 2), FDEffect(rel: "vestiaire", delta: -3)]),
        ]),
    FDSceneDef(
        id: "fin_derniere_blessure", category: "Retraite", minAge: 30, maxAge: 36,
        location: "Infirmerie", character: "Médecin du club",
        text: "Cinquième blessure musculaire de la saison, la troisième sur le même muscle. Le médecin ne prononce pas le mot, mais il pose la question autrement : est-ce que tu veux qu'on planifie quelque chose. Tu as trente-trois ans et il te reste un an de contrat.",
        choices: [
            FDChoice(label: "Écouter ton corps et planifier la fin", hint: "Tu as écouté ton corps et tu as planifié la fin. Une dernière demi-saison, propre, et une sortie choisie.",
                     effects: [FDEffect(cond: "moral", delta: 4), FDEffect(attr: .sangfroid, delta: 4), FDEffect(cond: "fatigue", delta: 5)]),
            FDChoice(label: "Repousser encore l'échéance", hint: "Tu as repoussé encore l'échéance. Tu as joué neuf matchs de plus, dont quatre entiers.",
                     effects: [FDEffect(attr: .determination, delta: 4), FDEffect(cond: "forme", delta: -6)]),
        ]),
    FDSceneDef(
        id: "sta_role_modele", category: "Star", minAge: 22, maxAge: 36,
        location: "Conférence dans un lycée", character: "Des lycéens",
        text: "Deux cents lycéens dans un gymnase d'un quartier où tu as grandi à trois kilomètres. On te demande de parler de ton parcours pendant quarante minutes. La moitié de la salle n'écoutera pas, et deux ou trois retiendront chaque mot pour très longtemps.",
        choices: [
            FDChoice(label: "Raconter les échecs autant que les réussites", hint: "Tu as raconté les échecs autant que les réussites : les essais ratés, les portes fermées, les doutes. La salle s'est tue au bout de cinq minutes.",
                     effects: [FDEffect(cond: "reputation", delta: 8), FDEffect(cond: "moral", delta: 6), FDEffect(rel: "fans", delta: 5), FDEffect(rel: "vestiaire", delta: -3), FDEffect(money: 12000, delta: 0)]),
            FDChoice(label: "Faire court", hint: "Tu as fait court, une vingtaine de minutes, et beaucoup de photos. Ils étaient contents, et ils n'ont rien retenu.",
