    FDSceneDef(
        id: "sta_retour_gagnant", category: "Star", minAge: 22, maxAge: 36,
        location: "Pelouse", character: "Le stade entier",
        text: "Premier match après trois mois d'absence, et le club joue sa saison ce soir. Le coach te laisse le choix : débuter, avec le risque de rechuter et de tout compromettre, ou entrer à l'heure de jeu, frais, quand les jambes des autres seront lourdes. Le stade veut te voir.",
